(window.QDATA=window.QDATA||{})[6]={"s":6,"ar":"الأنعام","tl":"Al-An'am","n":165,"place":"makkah","bism":true,"mean":{"en":"The Cattle","ur":"مویشی","hi":"मवेशी"},"v":[{"a":1,"ar":" ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَ ۖ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ","en":"[All] praise is [due] to Allāh, who created the heavens and the earth and made the darkness and the light. Then those who disbelieve equate [others] with their Lord.","ur":"ہر طرح کی تعریف خدا ہی کو سزاوار ہے جس نے آسمانوں اور زمین کو پیدا کیا اور اندھیرا اور روشنی بنائی پھر بھی کافر (اور چیزوں کو) خدا کے برابر ٹھیراتے ہیں","hi":"सब प्रशंसा उस अल्लाह के लिए है, जिसने आकाशों तथा धरती को पैदा किया और अँधेरों और प्रकाश को बनाया, फिर (भी) वे लोग जिन्होंने कुफ़्र किया, अपने रब के साथ (दूसरों को) बराबर ठहराते हैं।"},{"a":2,"ar":"هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا ۖ وَأَجَلٌ مُّسَمًّى عِندَهُۥ ۖ ثُمَّ أَنتُمْ تَمْتَرُونَ","en":"It is He who created you from clay and then decreed a term and a specified time [known] to Him; then [still] you are in dispute.","ur":"وہی تو ہے جس نے تم کو مٹی سے پیدا کیا پھر (مرنے کا) ایک وقت مقرر کر دیا اور ایک مدت اس کے ہاں اور مقرر ہے پھر بھی تم (اے کافرو خدا کے بارے میں) شک کرتے ہو","hi":"वही है जिसने तुम्हें तुच्छ मिट्टी से पैदा किया, फिर एक अवधि निर्धारित कर दी तथा एक और अवधि उसके पास निर्धारित है। फिर (भी) तुम संदेह करते हो।"},{"a":3,"ar":"وَهُوَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَفِى ٱلْأَرْضِ ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ","en":"And He is Allāh, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn.","ur":"اور آسمانوں اور زمین میں وہی (ایک) خدا ہے تمہاری پوشیدہ اور ظاہر سب باتیں جانتا ہے اور تم جو عمل کرتے ہو سب سے واقف ہے","hi":"तथा आकाशों में और धरती में वही (एकमात्र) अल्लाह है, वह तुम्हारे छिपे और तुम्हारे खुले को जानता है तथा जानता है जो तुम कमाते हो।"},{"a":4,"ar":"وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَـٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ","en":"And no sign comes to them from the signs of their Lord except that they turn away therefrom.","ur":"اور خدا کی نشانیوں میں سے کوئی نشانی ان لوگوں کے پاس نہیں آتی مگر یہ اس سے منہ پھیر لیتے ہیں","hi":"और उनके पास उनके पालनहार की आयतों (निशानियों) में से कोई आयत (निशानी) नहीं आती, परंतु वे उससे मुँह फेरने वाले होते हैं।"},{"a":5,"ar":"فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ ۖ فَسَوْفَ يَأْتِيهِمْ أَنۢبَـٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ","en":"For they had denied the truth when it came to them, but there is going to reach them the news of what they used to ridicule.","ur":"جب ان کے پاس حق آیا تو اس کو بھی جھٹلا دیا سو ان کو ان چیزوں کا جن سے یہ استہزا کرتے ہیں عنقریب انجام معلوم ہو جائے گا","hi":"चुनाँचे निःसंदेह उन्होंने सत्य को झुठला दिया, जब वह उनके पास आया। तो शीघ्र ही उनके पास उसके समाचार आ जाएँगे, जिसका वे उपहास किया करते हैं।"},{"a":6,"ar":"أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّـٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَـٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَـٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ","en":"Have they not seen how many generations We destroyed before them which We had established upon the earth as We have not established you? And We sent [rain from] the sky upon them in showers and made rivers flow beneath them; then We destroyed them for their sins and brought forth after them a generation of others.","ur":"کیا انہوں نے نہیں دیکھا کہ ہم نے ان سے پہلے کتنی امتوں کو ہلاک کر دیا جن کے پاؤں ملک میں ایسے جما دیئے تھے کہ تمہارے پاؤں بھی ایسے نہیں جمائے اور ان پر آسمان سے لگاتار مینہ برسایا اور نہریں بنا دیں جو ان کے (مکانوں کے) نیچے بہہ رہی تھیں پھر ان کو ان کے گناہوں کے سبب ہلاک کر دیا اور ان کے بعد اور امتیں پیدا کر دیں","hi":"क्या उन्होंने नहीं देखा कि हमने उनसे पहले कितने समुदायों को नष्ट कर दिया, जिन्हें हमने धरती में वह सत्ता (शक्ति एवं अधिकार) दी थी, जो सत्ता तुम्हें नहीं दी, और हमने उनपर मूसला धार वर्षा की, और हमने नहरें बनाईं, जो उनके नीचे से बहती थीं। फिर हमने उन्हें उनके पापों के कारण विनष्ट कर दिया, और उनके पश्चात् दूसरे समुदायों को पैदा कर दिया।"},{"a":7,"ar":"وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَـٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ","en":"And even if We had sent down to you, [O Muḥammad], a written scripture on a page and they touched it with their hands, the disbelievers would say, \"This is not but obvious magic.\"","ur":"اور اگر ہم تم پر کاغذوں پر لکھی ہوئی کتاب نازل کرتے اور یہ اسے اپنے ہاتھوں سے بھی ٹٹول لیتے تو جو کافر ہیں وہ یہی کہہ دیتے کہ یہ تو (صاف اور) صریح جادو ہے","hi":"(ऐ नबी!) यदि हम आपपर काग़ज़ में लिखी हुई कोई पुस्तक उतारते, फिर वे उसे अपने हाथों से छूते, तो निश्चय वे लोग जिन्होंने कुफ़्र किया, यही कहते कि यह तो स्पष्ट जादू के सिवा कुछ नहीं।"},{"a":8,"ar":"وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ ۖ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ","en":"And they say, \"Why was there not sent down to him an angel?\" But if We had sent down an angel, the matter would have been decided; then they would not be reprieved.","ur":"اور کہتے ہیں کہ ان (پیغمبر) پر فرشتہ کیوں نازل نہ ہوا (جو ان کی تصدیق کرتا) اگر ہم فرشتہ نازل کرتے تو کام ہی فیصل ہو جاتا پھر انھیں (مطلق) مہلت نہ دی جاتی","hi":"तथा उन्होंने कहा : इस (नबी) पर कोई फ़रिश्ता क्यों न उतारा गया? और यदि हम कोई फ़रिश्ता उतारते, तो अवश्य काम तमाम कर दिया जाता, फिर उन्हें मोहलत न दी जाती।"},{"a":9,"ar":"وَلَوْ جَعَلْنَـٰهُ مَلَكًا لَّجَعَلْنَـٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ","en":"And if We had made him [i.e., the messenger] an angel, We would have made him [appear as] a man, and We would have covered them with that in which they cover themselves [i.e., confusion and doubt].","ur":"نیز اگر ہم کسی فرشتہ کو بھیجتے تو اسے مرد کی صورت میں بھیجتے اور جو شبہ (اب) کرتے ہیں اسی شبے میں پھر انہیں ڈال دیتے","hi":"और यदि हम उसे फ़रिश्ता बनाते, तो निश्चय उसे आदमी (के रूप में) बनाते और अवश्य उनपर वही संदेह डाल देते, जिस संदेह में वे (अब) पड़े हुए हैं।"},{"a":10,"ar":"وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ","en":"And already were messengers ridiculed before you, but those who mocked them were enveloped by that which they used to ridicule.","ur":"اور تم سے پہلے بھی پیغمبروں کے ساتھ تمسخر ہوتے رہے ہیں سو جو لوگ ان میں سے تمسخر کیا کرتے تھے ان کو تمسخر کی سزا نے آگھیرا","hi":"और निःसंदेह (ऐ नबी!) आपसे पहले कई रसूलों का उपहास किया गया, तो उन लोगों को जिन्होंने उनमें से उपहास किया था, उसी चीज़ ने घेर लिया, जिसका वे उपहास किया करते थे।"},{"a":11,"ar":"قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ","en":"Say, \"Travel through the land; then observe how was the end of the deniers.\"","ur":"کہو کہ (اے منکرین رسالت) ملک میں چلو پھرو پھر دیکھو کہ جھٹلانے والوں کا کیا انجام ہوا","hi":"(ऐ नबी!) आप कह दें कि धरती में चलो-फिरो, फिर देखो कि झुठलाने वालों का परिणाम कैसा हुआ?"},{"a":12,"ar":"قُل لِّمَن مَّا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ قُل لِّلَّهِ ۚ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ ۚ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ","en":"Say, \"To whom belongs whatever is in the heavens and earth?\" Say, \"To Allāh.\" He has decreed upon Himself mercy. He will surely assemble you for the Day of Resurrection, about which there is no doubt. Those who will lose themselves [that Day] do not believe.","ur":"(ان سے) پوچھو کہ آسمان اور زمین میں جو کچھ ہے کس کا ہے کہہ دو خدا کا اس نے اپنی ذات (پاک) پر رحمت کو لازم کر لیا ہے وہ تم سب کو قیامت کے دن جس میں کچھ بھی شک نہیں ضرور جمع کرے گا جن لوگوں نے اپنے تیئیں نقصان میں ڈال رکھا ہے وہ ایمان نہیں لاتے","hi":"(ऐ नबी!) (उनसे) पूछिए कि जो कुछ आकाशों तथा धरती में है, वह किसका है? कह दें : अल्लाह का है! उसने अपने ऊपर दया करना लिख दिया है। निश्चय वह तुम्हें क़ियामत के दिन की ओर (ले जाकर) अवश्य एकत्र करेगा, जिसमें कोई संदेह नहीं। जिन लोगों ने अपने-आपको क्षति में डाला, वही ईमान नहीं लाते।"},{"a":13,"ar":"۞ وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","en":"And to Him belongs that which reposes by night and by day, and He is the Hearing, the Knowing.","ur":"اور جو مخلوق رات اور دن میں بستی ہے سب اسی کی ہے اور وہ سنتا جانتا ہے","hi":"तथा उसी (अल्लाह) का है, जो कुछ रात और दिन में बस रहा है और वह सब कुछ सुनने वाला, सब कुछ जानने वाला है।"},{"a":14,"ar":"قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ ۗ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ","en":"Say, \"Is it other than Allāh I should take as a protector, Creator of the heavens and earth, while it is He who feeds and is not fed?\" Say, [O Muḥammad], \"Indeed, I have been commanded to be the first [among you] who submit [to Allāh] and [was commanded], 'Do not ever be of the polytheists.\"","ur":"کہو کیا میں خدا کو چھوڑ کر کسی اور کو مددگار بناؤں کہ (وہی تو) آسمانوں اور زمین کا پیدا کرنے والا ہے اور وہی (سب کو) کھانا دیتا ہے اور خود کسی سے کھانا نہیں لیتا (یہ بھی) کہہ دو کہ مجھے یہ حکم ہوا ہے کہ میں سب سے پہلے اسلام لانے والا ہوں اور یہ کہ تم (اے پیغمبر!) مشرکوں میں نہ ہونا","hi":"(ऐ नबी!) कह दो : क्या मैं अल्लाह के सिवा कोई सहायक बनाऊँ, जो आकाशों तथा धरती का बनाने वाला है, हालाँकि वह खिलाता है और उसे नहीं खिलाया जाता। आप कहिए : निःसंदेह मुझे आदेश दिया गया है कि सबसे पहला व्यक्ति बनूँ जो आज्ञाकारी हुआ, तथा तुम कदापि साझी बनाने वालों में से न हो।"},{"a":15,"ar":"قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ","en":"Say, \"Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day.\"","ur":"(یہ بھی) کہہ دو کہ اگر میں اپنے پروردگار کی نافرمانی کروں تو مجھے بڑے دن کے عذاب کا خوف ہے","hi":"आप कह दें कि यदि मैं अपने पालनहार की अवज्ञा करूँ, तो निःसंदेह मैं एक बड़े दिन की यातना से डरता हूँ।"},{"a":16,"ar":"مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ","en":"He from whom it is averted that Day - [Allāh] has granted him mercy. And that is the clear attainment.","ur":"جس شخص سے اس روز عذاب ٹال دیا گیا اس پر خدا نے (بڑی) مہربانی فرمائی اور یہ کھلی کامیابی ہے","hi":"जिस व्यक्ति से उस दिन वह हटा लिया जाएगा, तो निश्चय अल्लाह ने उसपर दया कर दी और यही खुली सफलता है।"},{"a":17,"ar":"وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","en":"And if Allāh should touch you with adversity, there is no remover of it except Him. And if He touches you with good - then He is over all things competent.","ur":"اور اگر خدا تم کو کوئی سختی پہنچائے تو اس کے سوا اس کو کوئی دور کرنے والا نہیں اور اگر نعمت (وراحت) عطا کرے تو (کوئی اس کو روکنے والا نہیں) وہ ہر چیز پر قادر ہے","hi":"यदि अल्लाह तुझे कोई हानि पहुँचाए, तो उसके सिवा कोई उसे दूर करने वाला नहीं, और यदि वह तुझे कोई भलाई पहुँचाए, तो वह हर चीज़ पर सर्वशक्तिमान है।"},{"a":18,"ar":"وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ","en":"And He is the subjugator over His servants. And He is the Wise, the Aware.","ur":"اور وہ اپنے بندوں پر غالب ہے اور وہ دانا اور خبردار ہے","hi":"तथा वही अपने बंदों पर ग़ालिब (हावी) है तथा वही पूर्ण हिकमत वाला, हर चीज़ की ख़बर रखने वाला है।"},{"a":19,"ar":"قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَـٰدَةً ۖ قُلِ ٱللَّهُ ۖ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ ۚ وَأُوحِىَ إِلَىَّ هَـٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ ۚ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ ۚ قُل لَّآ أَشْهَدُ ۚ قُلْ إِنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ","en":"Say, \"What thing is greatest in testimony?\" Say, \"Allāh is witness between me and you. And this Qur’ān was revealed to me that I may warn you thereby and whomever it reaches. Do you [truly] testify that with Allāh there are other deities?\" Say, \"I will not testify [with you].\" Say, \"Indeed, He is but one God, and indeed, I am free of what you associate [with Him].\"","ur":"ان سے پوچھو کہ سب سے بڑھ کر (قرین انصاف) کس کی شہادت ہے کہہ دو کہ خدا ہی مجھ میں اور تم میں گواہ ہے اور یہ قرآن مجھ پر اس لیے اتارا گیا ہے کہ اس کے ذریعے سے تم کو اور جس شخص تک وہ پہنچ سکے آگاہ کردوں کیا تم لوگ اس بات کی شہادت دیتے ہو کہ خدا کے ساتھ اور بھی معبود ہیں (اے محمدﷺ!) کہہ دو کہ میں تو (ایسی) شہادت نہیں دیتا کہہ دو کہ صرف وہی ایک معبود ہے اور جن کو تم لوگ شریک بناتے ہو میں ان سے بیزار ہوں","hi":"(ऐ नबी!) आप (इन मुश्रिकों से) पूछें कि कौन-सी चीज़ गवाही में सबसे बड़ी है? आप कह दें कि अल्लाह मेरे और तुम्हारे बीच गवाह है तथा मेरी ओर यह क़ुरआन वह़्य (प्रकाशना) द्वारा भेजा गया है, ताकि मैं तुम्हें इसके द्वारा डराऊँ और उसे भी जिस तक यह पहुँचे। क्या निःसंदेह तुम वास्तव में यह गवाही देते हो कि बेशक अल्लाह के साथ कुछ और पूज्य भी हैं? आप कह दें कि मैं तो इसकी गवाही नहीं देता। आप कह दें कि वह तो केवल एक ही पूज्य है तथा निःसंदेह मैं उससे बरी हूँ जो तुम शरीक ठहराते हो।"},{"a":20,"ar":"ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ۘ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ","en":"Those to whom We have given the Scripture recognize it as they recognize their [own] sons. Those who will lose themselves [in the Hereafter] do not believe.","ur":"جن لوگوں کو ہم نے کتاب دی ہے وہ ان (ہمارے پیغمبرﷺ) کو اس طرح پہچانتے ہیں جس طرح اپنے بیٹوں کو پہچانا کرتے ہیں جنہوں نے اپنے تئیں نقصان میں ڈال رکھا ہے وہ ایمان نہیں لاتے","hi":"जिन लोगों को हमने पुस्तक प्रदान की, वे उसे उसी प्रकार पहचानते हैं, जैसे वे अपने बेटों को पहचानते हैं। वे लोग जिन्होंने स्वयं को क्षति में डाला, तो वे ईमान नहीं लाते।"},{"a":21,"ar":"وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ","en":"And who is more unjust than one who invents about Allāh a lie or denies His verses? Indeed, the wrongdoers will not succeed.","ur":"اور اس شخص سے زیادہ کون ظالم ہے جس نے خدا پر جھوٹ افتراء کیا یا اس کی آیتوں کو جھٹلایا۔ کچھ شک نہیں کہ ظالم لوگ نجات نہیں پائیں گے","hi":"तथा उससे बड़ा अत्याचारी कौन है, जिसने अल्लाह पर कोई झूठ गढ़ा, या उसकी आयतों को झुठलाया। निःसंदेह अत्याचारी कभी सफल नहीं होते।"},{"a":22,"ar":"وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ","en":"And [mention, O Muḥammad], the Day We will gather them all together; then We will say to those who associated others with Allāh, \"Where are your 'partners' that you used to claim [with Him]?\"","ur":"اور جس دن ہم سب لوگوں کو جمع کریں گے پھر مشرکوں سے پوچھیں گے کہ (آج) وہ تمہارے شریک کہاں ہیں جن کو تمہیں دعویٰ تھا","hi":"और जिस दिन हम उन सबको एकत्र करेंगे, फिर हम उन लोगों से कहेंगे, जिन्होंने साझी ठहराए : तुम्हारे वे साझी कहाँ हैं, जिनका तुम दावा करते थे?"},{"a":23,"ar":"ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ","en":"Then there will be no [excuse upon] examination except they will say, \"By Allāh, our Lord, we were not those who associated.\"","ur":"تو ان سے کچھ عذر نہ بن پڑے گا (اور) بجز اس کے (کچھ چارہ نہ ہوگا) کہ کہیں خدا کی قسم جو ہمارا پروردگار ہے ہم شریک نہیں بناتے تھے","hi":"फिर उनका कोई बहाना न होगा सिवाय इसके कि वे कहेंगे : अल्लाह की क़सम! जो हमारा पालनहार है, हम मुश्रिक न थे।"},{"a":24,"ar":"ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ ۚ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ","en":"See how they will lie about themselves. And lost from them will be what they used to invent.","ur":"دیکھو انہوں نے اپنے اوپر کیسا جھوٹ بولا اور جو کچھ یہ افتراء کیا کرتے تھے سب ان سے جاتا رہا","hi":"देखो उन्होंने कैसे अपने आपपर झूठ बोला और उनसे गुम हो गया, जो वे झूठ बनाया करते थे।"},{"a":25,"ar":"وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ ۖ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا ۚ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا ۚ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَـٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ","en":"And among them are those who listen to you, but We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if they should see every sign, they will not believe in it. Even when they come to you arguing with you, those who disbelieve say, \"This is not but legends of the former peoples.\"","ur":"اور ان میں بعض ایسے ہیں کہ تمہاری (باتوں کی) طرف کان رکھتے ہیں۔ اور ہم نے ان کے دلوں پر تو پردے ڈال دیئے ہیں کہ ان کو سمجھ نہ سکیں اور کانوں میں ثقل پیدا کردیا ہے (کہ سن نہ سکیں) اور اگر یہ تمام نشانیاں بھی دیکھ لیں تب بھی ان پر ایمان نہ لائیں۔ یہاں تک کہ جب تمہارے پاس تم سے بحث کرنے کو آتے ہیں تو جو کافر ہیں کہتے ہیں یہ (قرآن) اور کچھ بھی نہیں صرف پہلے لوگوں کی کہانیاں ہیں","hi":"और उनमें से कुछ ऐसे हैं जो आपकी ओर कान लगाते हैं, और हमने उनके दिलों पर परदे डाल दिए हैं, कि बात न समझें और उनके कानों में बोझ डाल दिया है। यदि वे प्रत्येक निशानी देख लें, (तब भी) उसपर ईमान नहीं लाएँगे, यहाँ तक कि जब वे आपके पास झगड़ते हुए आते हैं, तो वे लोग जिन्होंने कुफ़्र किया, कहते हैं : ये पहले लोगों की कल्पित कथाओं के सिवा कुछ नहीं।"},{"a":26,"ar":"وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ ۖ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ","en":"And they prevent [others] from him and are [themselves] remote from him. And they do not destroy except themselves, but they perceive [it] not.","ur":"وہ اس سے (اوروں کو بھی) روکتے ہیں اور خود بھی پرے رہتے ہیں مگر (ان باتوں سے) اپنے آپ ہی کو ہلاک کرتے ہیں اور (اس سے) بےخبر ہیں","hi":"और वे उससे (लोगों को) रोकते हैं और (स्वयं भी) उससे दूर रहते हैं, और वे मात्र अपने आपको विनष्ट कर रहे हैं और वे नहीं समझते।"},{"a":27,"ar":"وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَـٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَـٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ","en":"If you could but see when they are made to stand before the Fire and will say, \"Oh, would that we could be returned [to life on earth] and not deny the signs of our Lord and be among the believers.\"","ur":"کاش تم (ان کو اس وقت) دیکھو جب یہ دوزخ کے کنارے کھڑے کئے جائیں گے اور کہیں گے کہ اے کاش ہم پھر (دنیا میں) لوٹا دیئے جائیں تاکہ اپنے پروردگار کی آیتوں کی تکذیب نہ کریں اور مومن ہوجائیں","hi":"तथा (ऐ नबी!) यदि आप उस समय देखें, जब वे आग पर खड़े किए जाएँगे, तो वे कहेंगे : ऐ काश! हम वापस भेजे जाएँ और अपने पालनहार की आयतों को न झुठलाएँ और हम ईमान वालों में से हो जाएँ।"},{"a":28,"ar":"بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ ۖ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَـٰذِبُونَ","en":"But what they concealed before has [now] appeared to them. And even if they were returned, they would return to that which they were forbidden; and indeed, they are liars.","ur":"ہاں یہ جو کچھ پہلے چھپایا کرتے تھے (آج) ان پر ظاہر ہوگیا ہے اور اگر یہ (دنیا میں) لوٹائے بھی جائیں تو جن (کاموں) سے ان کو منع کیا گیا تھا وہی پھر کرنے لگیں۔کچھ شک نہیں کہ یہ جھوٹے ہیں","hi":"बल्कि उनके लिए वह प्रकट हो गया, जो वे इससे पहले छिपाते थे। और यदि उन्हें वापस भेज दिया जाए, तो अवश्य फिर वही करेंगे, जिससे उन्हें रोका गया था। और निःसंदेह वे निश्चय झूठे हैं।"},{"a":29,"ar":"وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ","en":"And they say, \"There is none but our worldly life, and we will not be resurrected.\"","ur":"اور کہتے ہیں کہ ہماری جو دنیا کی زندگی ہے بس یہی (زندگی) ہے اور ہم (مرنے کے بعد) پھر زندہ نہیں کئے جائیں گے","hi":"और उन्होंने कहा : जीवन तो बस यही हमारा सांसारिक जीवन है। और हम हरगिज़ उठाए जाने वाले नहीं।"},{"a":30,"ar":"وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ ۚ قَالَ أَلَيْسَ هَـٰذَا بِٱلْحَقِّ ۚ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ","en":"If you could but see when they will be made to stand before their Lord. He will say, \"Is this not the truth?\" They will say, \"Yes, by our Lord.\" He will [then] say, \"So taste the punishment for what you used to deny.\"","ur":"اور کاش تم (ان کو اس وقت) دیکھو جب یہ اپنے پروردگار کےسامنے کھڑے کئے جائیں گے اور وہ فرمائےگا کیا یہ (دوبارہ زندہ ہونا) برحق نہیں تو کہیں گے کیوں نہیں پروردگار کی قسم (بالکل برحق ہے)خدا فرمائے گا اب کفر کے بدلے (جو دنیا میں کرتے تھے) عذاب (کے مزے) چکھو","hi":"तथा यदि आप उस समय देखें, जब वे अपने पालनहार के समक्ष खड़े किए जाएँगे।वह कहेगा : क्या यह (जीवन) सत्य नहीं है? वे कहेंगे : क्यों नहीं, हमारे पालनहार की क़सम! वह (अल्लाह) कहेगा : तो अब यातना चखो उसके बदले जो तुम कुफ़्र किया करते थे।"},{"a":31,"ar":"قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَـٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ ۚ أَلَا سَآءَ مَا يَزِرُونَ","en":"Those will have lost who deny the meeting with Allāh, until when the Hour [of resurrection] comes upon them unexpectedly, they will say, \"Oh, [how great is] our regret over what we neglected concerning it [i.e., the Hour],\" while they bear their burdens [i.e., sins] on their backs. Unquestionably, evil is that which they bear.","ur":"جن لوگوں نے خدا کے روبرو حاضر ہونے کو جھوٹ سمجھا وہ گھاٹے میں آگئے۔ یہاں تک کہ جب ان پر قیامت ناگہاں آموجود ہوگی تو بول اٹھیں گے کہ (ہائے) اس تقصیر پر افسوس ہے جو ہم نے قیامت کے بارے میں کی۔ اور وہ اپنے (اعمال کے) بوجھ اپنی پیٹھوں پر اٹھائے ہوئے ہوں گے۔ دیکھو جو بوجھ یہ اٹھا رہے ہیں بہت برا ہے","hi":"निश्चय वे लोग घाटे में रहे, जिन्होंने अल्लाह से मिलने को झुठलाया, यहाँ तक कि जब क़ियामत उनपर अचानक आ पहुँचेगी, तो कहेंगे : हाय अफ़सोस! उसपर जो हमने इसमें कोताही की। और वे अपने (पापों के) बोझ अपनी पीठों पर उठाए होंगे। सुन लो! बहुत बुरा बोझ है, जो वे उठाएँगे।"},{"a":32,"ar":"وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ ۖ وَلَلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ","en":"And the worldly life is not but amusement and diversion; but the home of the Hereafter is best for those who fear Allāh, so will you not reason?","ur":"اور دنیا کی زندگی تو ایک کھیل اور مشغولہ ہے۔ اور بہت اچھا گھر تو آخرت کا گھر ہے (یعنی) ان کے لئے جو (خدا سے) ڈرتے ہیں۔ کیا تم سمجھتے نہیں","hi":"तथा सांसारिक जीवन खेल और मनोरंजन के सिवा कुछ नहीं, तथा निश्चय आख़िरत का घर उन लोगों के लिए बेहतर है जो (अल्लाह से) डरते हैं, तो क्या तुम नहीं समझते?"},{"a":33,"ar":"قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ ۖ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَـٰكِنَّ ٱلظَّـٰلِمِينَ بِـَٔايَـٰتِ ٱللَّهِ يَجْحَدُونَ","en":"We know that you, [O Muḥammad], are saddened by what they say. And indeed, they do not call you untruthful, but it is the verses of Allāh that the wrongdoers reject.","ur":"ہم کو معلوم ہے کہ ان (کافروں) کی باتیں تمہیں رنج پہنچاتی ہیں (مگر) یہ تمہاری تکذیب نہیں کرتے بلکہ ظالم خدا کی آیتوں سے انکار کرتے ہیں","hi":"निःसंदेह हम जानते हैं कि निश्चय (ऐ नबी!) आपको वह बात दुखी करती है, जो वे कहते हैं। तो वास्तव में वे आपको नहीं झुठलाते, परंतु वे अत्याचारी अल्लाह की आयतों ही का इनकार करते हैं।"},{"a":34,"ar":"وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا ۚ وَلَا مُبَدِّلَ لِكَلِمَـٰتِ ٱللَّهِ ۚ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ","en":"And certainly were messengers denied before you, but they were patient over the denial, and they were harmed until Our victory came to them. And none can alter the words [i.e., decrees] of Allāh. And there has certainly come to you some information about the [previous] messengers.","ur":"اور تم سے پہلے کبھی پیغمبر جھٹلائے جاتے رہے تو وہ تکذیب اور ایذا پر صبر کرتے رہے یہاں تک کہ ان کے پاس ہماری مدد پہنچتی رہی اور خدا کی باتوں کو کوئی بھی بدلنے والا نہیں۔ اور تم کو پیغمبروں (کے احوال) کی خبریں پہنچ چکی ہیں (تو تم بھی صبر سے کام لو)","hi":"और निःसंदेह आपसे पहले कई रसूल झुठलाए गए, तो उन्होंने अपने झुठलाए जाने और कष्ट दिए जाने पर सब्र किया, यहाँ तक कि उनके पास हमारी सहायता आ गई। तथा कोई अल्लाह की बातों को बदलने वाला नहीं और निःसंदेह आपके पास (उन) रसूलों के कुछ समाचार आ चुके हैं।"},{"a":35,"ar":"وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ ۚ فَلَا تَكُونَنَّ مِنَ ٱلْجَـٰهِلِينَ","en":"And if their evasion is difficult for you, then if you are able to seek a tunnel into the earth or a stairway into the sky to bring them a sign, [then do so]. But if Allāh had willed, He would have united them upon guidance. So never be of the ignorant.","ur":"اور اگر ان کی روگردانی تم پر شاق گزرتی ہے تو اگر طاقت ہو تو زمین میں کوئی سرنگ ڈھونڈ نکالو یا آسمان میں سیڑھی (تلاش کرو) پھر ان کے پاس کوئی معجزہ لاؤ۔ اور اگر خدا چاہتا تو سب کو ہدایت پر جمع کردیتا پس تم ہرگز نادانوں میں نہ ہونا","hi":"और यदि आपपर उनकी विमुखता भारी गुज़र रही है, तो यदि आपसे हो सके कि धरती में कोई सुरंग अथवा आकाश में कोई सीढ़ी ढूँढ निकालें, फिर उनके पास कोई निशानी (चमत्कार) ले आएँ, (तो ले आएँ) और यदि अल्लाह चाहता, तो निश्चय उन्हें मार्गदर्शन पर एकत्र कर देता। अतः आप कदापि अज्ञानियों में से न हों।"},{"a":36,"ar":"۞ إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ ۘ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ","en":"Only those who hear will respond. But the dead - Allāh will resurrect them; then to Him they will be returned.","ur":"بات یہ ہے کہ (حق کو) قبول وہی کرتے ہیں جو سنتے بھی ہیں اور مردوں کو تو خدا (قیامت ہی کو) اٹھائے گا۔ پھر اسی کی طرف لوٹ کر جائیں گے","hi":"स्वीकार तो केवल वही लोग करते हैं, जो सुनते हैं। और जो मुर्दे हैं, उन्हें अल्लाह उठाएगा, फिर वे उसी की ओर लौटाए जाएँगे।"},{"a":37,"ar":"وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۚ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ","en":"And they say, \"Why has a sign not been sent down to him from his Lord?\" Say, \"Indeed, Allāh is Able to send down a sign, but most of them do not know.\"","ur":"اور کہتے ہیں کہ ان پر ان کے پروردگارکے پاس کوئی نشانی کیوں نازل نہیں ہوئی۔ کہہ دو کہ خدا نشانی اتارنے پر قادر ہے لیکن اکثر لوگ نہیں جانتے","hi":"तथा उन्होंने कहा : उस (नबी) पर उसके पालनहार की ओर से कोई निशानी क्यों नहीं उतारी गई? आप कह दें : निःसंदेह अल्लाह इसका सामर्थ्य रखता है कि कोई निशानी उतारे, परंतु उनके अधिकतर लोग नहीं जानते।"},{"a":38,"ar":"وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَـٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم ۚ مَّا فَرَّطْنَا فِى ٱلْكِتَـٰبِ مِن شَىْءٍ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ","en":"And there is no creature on [or within] the earth or bird that flies with its wings except [that they are] communities like you. We have not neglected in the Register a thing. Then unto their Lord they will be gathered.","ur":"اور زمین میں جو چلنے پھرنے والا (حیوان) یا دو پروں سے اڑنے والا جانور ہے ان کی بھی تم لوگوں کی طرح جماعتیں ہیں۔ ہم نے کتاب (یعنی لوح محفوظ) میں کسی چیز (کے لکھنے) میں کوتاہی نہیں کی پھر سب اپنے پروردگار کی طرف جمع کئے جائیں گے","hi":"तथा धरती में न कोई चलने वाला है तथा न कोई उड़ने वाला, जो अपने दो पंखों से उड़ता है, परंतु तुम्हारी जैसी जातियाँ हैं। हमने पुस्तक में किसी चीज़ की कमी नहीं छोड़ी। फिर वे अपने पालनहार की ओर एकत्र किए जाएँगे।"},{"a":39,"ar":"وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَـٰتِ ۗ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ","en":"But those who deny Our verses are deaf and dumb within darknesses. Whomever Allāh wills - He sends astray; and whomever He wills - He puts him on a straight path.","ur":"اور جن لوگوں نے ہماری آیتوں کو جھٹلایا وہ بہرے اور گونگے ہیں (اس کے علاوہ) اندھیرے میں (پڑے ہوئے) جس کو خدا چاہے گمراہ کردے اور جسے چاہے سیدھے رستے پر چلا دے","hi":"तथा जिन लोगों ने हमारी आयतों (निशानियों) को झुठलाया, वे बहरे और गूँगे है, अँधेरों में पड़े हुए हैं। जिसे अल्लाह चाहता है, पथभ्रष्ट कर देता है और जिसे चाहता है, सीधे मार्ग पर लगा देता है।"},{"a":40,"ar":"قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَـٰدِقِينَ","en":"Say, \"Have you considered: if there came to you the punishment of Allāh or there came to you the Hour - is it other than Allāh you would invoke, if you should be truthful?\"","ur":"کہو (کافرو) بھلا دیکھو تو اگر تم پر خدا کا عذاب آجائےیا قیامت آموجود ہو تو کیا تم (ایسی حالت میں) خدا کے سوا کسی اور کو پکارو گے؟ اگر سچے ہو (تو بتاؤ)","hi":"(ऐ नबी!) उनसे कहो, भला बताओ तो सही कि यदि तुमपर अल्लाह की यातना आ जाए, या तुमपर क़ियामत आ जाए, तो क्या तुम अल्लाह के सिवा किसी और को पुकारोगे? यदि तुम सच्चे हो।"},{"a":41,"ar":"بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ","en":"No, it is Him [alone] you would invoke, and He would remove that for which you invoked Him if He willed, and you would forget what you associate [with Him].","ur":"بلکہ (مصیبت کے وقت تم) اسی کو پکارتے ہو تو جس دکھ کے لئے اسے پکارتے ہو۔ وہ اگر چاہتا ہے تو اس کو دور کردیتا ہے اور جن کو تم شریک بناتے ہو (اس وقت) انہیں بھول جاتے ہو","hi":"बल्कि तुम उसी को पुकारोगे, फिर वह दूर कर देगा (उस विपत्ति को) जिसके लिए तुम उसे पुकारोगे, यदि उसने चाहा, और तुम भूल जाओगे जिसे साझी बनाते हो।"},{"a":42,"ar":"وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَـٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ","en":"And We have already sent [messengers] to nations before you, [O Muḥammad]; then We seized them with poverty and hardship that perhaps they might humble themselves [to Us].","ur":"اور ہم نے تم سے پہلے بہت سی امتوں کی طرف پیغمبر بھیجے۔ پھر (ان کی نافرمانیوں کے سبب) ہم انہیں سختیوں اور تکلیفوں میں پکڑتے رہے تاکہ عاجزی کریں","hi":"और निःसंदेह हमने आपसे पहले कई समुदायों की ओर रसूल भेजे, फिर हमने उन्हें दरिद्रता और कष्ट के साथ पकड़ा, ताकि वे गिड़गिड़ाएँ।"},{"a":43,"ar":"فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَـٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ مَا كَانُوا۟ يَعْمَلُونَ","en":"Then why, when Our punishment came to them, did they not humble themselves? But their hearts became hardened, and Satan made attractive to them that which they were doing.","ur":"تو جب ان پر ہمارا عذاب آتا رہا کیوں نہیں عاجزی کرتے رہے۔ مگر ان کے تو دل ہی سخت ہوگئے تھے۔ اور جو وہ کام کرتے تھے شیطان ان کو (ان کی نظروں میں) آراستہ کر دکھاتا تھا","hi":"फिर वे क्यों न गिड़गिड़ाए, जब उनपर हमारी यातना आई? परंतु उनके दिल कठोर हो गए तथा शैतान ने उनके लिए उसे सुंदर बना दिया, जो कुछ वे किया करते थे।"},{"a":44,"ar":"فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَـٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ","en":"So when they forgot that by which they had been reminded, We opened to them the doors of every [good] thing until, when they rejoiced in that which they were given, We seized them suddenly, and they were [then] in despair.","ur":"پھر جب انہوں نے اس نصیحت کو جو ان کو گی گئی تھی فراموش کردیا تو ہم نے ان پر ہر چیز کے دروازے کھول دیئے۔ یہاں تک کہ جب ان چیزوں سے جو ان کو دی گئی تھیں خوب خوش ہوگئے تو ہم نے ان کو ناگہاں پکڑ لیا اور وہ اس وقت مایوس ہو کر رہ گئے","hi":"फिर जब वे उसको भूल गए, जिसका उन्हें उपदेश दिया गया था, तो हमने उनपर हर चीज़ के द्वार खोल दिए। यहाँ तक कि जब वे उन चीज़ों पर खुश हो गए, जो उन्हें दी गई थीं, हमने उन्हें अचानक पकड़ लिया तो वे निराश होकर रह गए।"},{"a":45,"ar":"فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ ۚ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ","en":"So the people that committed wrong were eliminated. And praise to Allāh, Lord of the worlds.","ur":"غرض ظالم لوگوں کی جڑ کاٹ دی گئی۔ اور سب تعریف خدائے رب العالمین ہی کو (سزاوار ہے)","hi":"तो उन लोगों की जड़ काट दी गई, जिन्होंने अत्याचार किया। और सब प्रशंसा अल्लाह ही के लिए है, जो सारे संसारों का पालनहार है।"},{"a":46,"ar":"قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَـٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَـٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَـٰتِ ثُمَّ هُمْ يَصْدِفُونَ","en":"Say, \"Have you considered: if Allāh should take away your hearing and your sight and set a seal upon your hearts, which deity other than Allāh could bring them [back] to you?\" Look how We diversify the verses; then they [still] turn away.","ur":"(ان کافروں سے) کہو کہ بھلا دیکھو تو اگر خدا تمہارے کان اور آنکھیں چھین لے اور تمہارے دلوں پر مہر لگادے تو خداکے سوا کون سا معبود ہے جو تمہیں یہ نعمتیں پھر بخشے؟ دیکھو ہم کس کس طرح اپنی آیتیں بیان کرتے ہیں۔ پھر بھی یہ لوگ ردگردانی کرتے ہیں","hi":"ऐ नबी! आप कह दें कि भला बताओ तो सही कि यदि अल्लाह तुम्हारे सुनने तथा देखने की शक्ति छीन ले और तुम्हारे दिलों पर मुहर लगा दे, तो अल्लाह के सिवा कौन-सा पूज्य है, जो तुम्हें ये चीज़ें लाकर दे? देखो, हम कैसे तरह-तरह से आयतें बयान करते हैं, फिर (भी) वे मुँह फेर लेते हैं।"},{"a":47,"ar":"قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّـٰلِمُونَ","en":"Say, \"Have you considered: if the punishment of Allāh should come to you unexpectedly or manifestly, will any be destroyed but the wrongdoing people?\"","ur":"کہو کہ بھلا بتاؤ تو اگر تم پر خدا کا عذاب بےخبری میں یا خبر آنے کے بعد آئے تو کیا ظالم لوگوں کے سوا کوئی اور بھی ہلاک ہوگا؟","hi":"आप कह दें, भला बताओ तो सही कि यदि तुमपर अल्लाह की यातना अचानक या खुल्लम-खुल्ला आ जाए, तो क्या अत्याचारी लोगों के सिवा कोई और विनष्ट किया जाएगा?"},{"a":48,"ar":"وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۖ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","en":"And We send not the messengers except as bringers of good tidings and warners. So whoever believes and reforms - there will be no fear concerning them, nor will they grieve.","ur":"اور ہم جو پیغمبروں کو بھیجتے رہے ہیں تو خوشخبری سنانے اور ڈرانے کو پھر جو شخص ایمان لائے اور نیکوکار ہوجائے تو ایسے لوگوں کو نہ کچھ خوف ہوگا اور نہ وہ اندوہناک ہوں گے","hi":"और हम रसूलों को केवल इसलिए भेजते हैं कि वे (आज्ञाकारियों को) शुभ सूचना दें तथा (अवज्ञाकारियों को) डराएँ। फिर जो व्यक्ति ईमान ले आए और अपना सुधार कर ले, तो उनपर कोई भय नहीं और न वे शोकाकुल होंगे।"},{"a":49,"ar":"وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ","en":"But those who deny Our verses - the punishment will touch them for their defiant disobedience.","ur":"اور جنہوں نے ہماری آیتوں کو جھٹلایا ان کی نافرمانیوں کے سبب انہیں عذاب ہوگا","hi":"और जिन लोगों ने हमारी आयतों को झुठलाया, उन्हें यातना पहुँचेगी इस कारणवश कि वे अवज्ञा करते थे।"},{"a":50,"ar":"قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ ۚ أَفَلَا تَتَفَكَّرُونَ","en":"Say, [O Muḥammad], \"I do not tell you that I have the depositories [containing the provision] of Allāh or that I know the unseen, nor do I tell you that I am an angel. I only follow what is revealed to me.\" Say, \"Is the blind equivalent to the seeing? Then will you not give thought?\"","ur":"کہہ دو کہ میں تم سے یہ نہیں کہتا کہ میرے پاس الله تعالیٰ کے خزانے ہیں اور نہ (یہ کہ) میں غیب جانتا ہوں اور نہ تم سے یہ کہتا کہ میں فرشتہ ہوں۔ میں تو صرف اس حکم پر چلتا ہوں جو مجھے (خدا کی طرف سے) آتا ہے۔ کہہ دو کہ بھلا اندھا اور آنکھ والے برابر ہوتے ہیں؟ تو پھر تم غور کیوں نہیں کرتے","hi":"(ऐ नबी!) आप कह दें : मैं तुमसे यह नहीं कहता कि मेरे पास अल्लाह के ख़ज़ाने हैं, और न मैं परोक्ष (ग़ैब) का ज्ञान रखता हूँ, और न मैं तुमसे यह कहता हूँ कि मैं कोई फ़रिश्ता हूँ। मैं तो केवल उसी का अनुसरण करता हूँ, जो मेरी ओर वह़्य (प्रकाशना) की जाती है। आप कह दें : क्या अंधा और देखने वाला बराबर होते हैं? तो क्या तुम सोच-विचार नहीं करते?"},{"a":51,"ar":"وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ ۙ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ","en":"And warn by it [i.e., the Qur’ān] those who fear that they will be gathered before their Lord - for them besides Him will be no protector and no intercessor - that they might become righteous.","ur":"اور جو لوگ جو خوف رکھتے ہیں کہ اپنے پروردگار کے روبرو حاضر کئے جائیں گے (اور جانتے ہیں کہ) اس کے سوا نہ تو ان کا کوئی دوست ہوگا اور نہ سفارش کرنے والا، ان کو اس (قرآن) کے ذریعے سے نصیحت کر دو تاکہ پرہیزگار بنیں","hi":"और इस (क़ुरआन) के द्वारा उन लोगों को डराएँ, जो इस बात का भय रखते हैं कि वे अपने पालनहार के पास (क़ियामत के दिन) एकत्र किए जाएँगे, उनके लिए उस (अल्लाह) के सिवा न कोई सहायक होगा और न कोई सिफ़ारिशी, ताकि वे (अल्लाह से) डरें।"},{"a":52,"ar":"وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّـٰلِمِينَ","en":"And do not send away those who call upon their Lord morning and afternoon, seeking His face [i.e., favor]. Not upon you is anything of their account and not upon them is anything of your account. So were you to send them away, you would [then] be of the wrongdoers.","ur":"اور جو لوگ صبح وشام اپنی پروردگار سے دعا کرتے ہیں (اور) اس کی ذات کے طالب ہیں ان کو (اپنے پاس سے) مت نکالو۔ ان کے حساب (اعمال) کی جوابدہی تم پر کچھ نہیں اور تمہارے حساب کی جوابدہی ان پر کچھ نہیں (پس ایسا نہ کرنا) اگر ان کو نکالوگے تو ظالموں میں ہوجاؤ گے","hi":"तथा (ऐ नबी!) आप उन लोगों को (अपने से) दूर न करें, जो सुबह और शाम अपने पालनहार को पुकारते हैं, वे उसका चेहरा चाहते हैं। आपपर उनके हिसाब में से कुछ नहीं और न आपके हिसाब में से उनपर कुछ है कि आप उन्हें दूर हटा दें, फिर आप अत्याचारियों में से हो जाएँ।"},{"a":53,"ar":"وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَـٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ ۗ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّـٰكِرِينَ","en":"And thus We have tried some of them through others that they [i.e., the disbelievers] might say, \"Is it these whom Allāh has favored among us?\" Is not Allāh most knowing of those who are grateful?","ur":"اور اسی طرح ہم نے بعض لوگوں کی بعض سے آزمائش کی ہے کہ (جو دولتمند ہیں وہ غریبوں کی نسبت) کہتے ہیں کیا یہی لوگ ہیں جن پر خدا نے ہم میں سے فضل کیا ہے (خدا نے فرمایا) بھلا خدا شکر کرنے والوں سے واقف نہیں؟","hi":"और इसी प्रकार हमने उनमें से कुछ को कुछ के द्वारा परीक्षा में डाला, ताकि वे कहें : क्या यही लोग हैं, जिनपर अल्लाह ने हमारे बीच में से उपकार किया है? क्या अल्लाह शुक्र करने वालों को अधिक जानने वाला नहीं?"},{"a":54,"ar":"وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَـٰتِنَا فَقُلْ سَلَـٰمٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۖ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَـٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ","en":"And when those come to you who believe in Our verses, say, \"Peace be upon you. Your Lord has decreed upon Himself mercy: that any of you who does wrong out of ignorance and then repents after that and corrects himself - indeed, He is Forgiving and Merciful.\"","ur":"اور جب تمہارے پاس ایسے لوگ آیا کریں جو ہماری آیتوں پر ایمان لاتے ہیں تو (ان سے) سلام علیکم کہا کرو خدا نے اپنی ذات (پاک) پر رحمت کو لازم کرلیا ہے کہ جو کوئی تم میں نادانی سے کوئی بری حرکت کر بیٹھے پھر اس کے بعد توبہ کرلے اور نیکوکار ہوجائے تو وہ بخشنے والا مہربان ہے","hi":"तथा (ऐ नबी!) जब आपके पास वे लोग आएँ, जो हमारी आयतों (क़ुरआन) पर ईमान रखते हैं, तो आप कह दें कि तुमपर सलाम (शांति) है। तुम्हारे रब ने दया करना अपने ऊपर अनिवार्य कर लिया है कि निःसंदेह तुममें से जो व्यक्ति अज्ञानतावश कोई बुराई करे, फिर उसके पश्चात् तौबा (क्षमा याचना) करे और अपना सुधार कर ले, तो निश्चय वह (अल्लाह) अति क्षमाशील, अत्यंत दयावान् है।"},{"a":55,"ar":"وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ","en":"And thus do We detail the verses, and [thus] the way of the criminals will become evident.","ur":"اور اس طرح ہم اپنی آیتیں کھول کھول کر بیان کرتے ہیں (تاکہ تم لوگ ان پر عمل کرو) اور اس لئے کہ گنہگاروں کا رستہ ظاہر ہوجائے","hi":"और इसी प्रकार हम आयतों को खोलकर बयान करते हैं और ताकि अपराधियों का मार्ग स्पष्ट हो जाए।"},{"a":56,"ar":"قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ ۚ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ ۙ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ","en":"Say, \"Indeed, I have been forbidden to worship those you invoke besides Allāh.\" Say, \"I will not follow your desires, for I would then have gone astray, and I would not be of the [rightly] guided.\"","ur":"(اے پیغمبر! کفار سے) کہہ دو کہ جن کو تم خدا کے سوا پکارتے ہو مجھے ان کی عبادت سے منع کیا گیا ہے۔ (یہ بھی) کہہ دو کہ میں تمہاری خواہشوں کی پیروی نہیں کروں گا ایسا کروں تو گمراہ ہوجاؤں اور ہدایت یافتہ لوگوں میں نہ رہوں","hi":"(ऐ नबी!) आप (मुश्रिकों से) कह दें : निःसंदेह मुझे मना किया गया है कि मैं उनकी इबादत करूँ, जिन्हें तुम अल्लाह के सिवा पुकारते हो। आप कह दें : मैं तुम्हारी इच्छाओं के पीछे नहीं चलता। निश्चय मैं उस समय पथभ्रष्ट हो गया और मैं मार्गदर्शन पाने वालो में से न रहा।"},{"a":57,"ar":"قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ ۚ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ يَقُصُّ ٱلْحَقَّ ۖ وَهُوَ خَيْرُ ٱلْفَـٰصِلِينَ","en":"Say, \"Indeed, I am on clear evidence from my Lord, and you have denied it. I do not have that for which you are impatient. The decision is only for Allāh. He relates the truth, and He is the best of deciders.\"","ur":"کہہ دو کہ میں تو اپنے پروردگار کی دلیل روشن پر ہوں اور تم اس کی تکذیب کرتے ہو۔ جس چیز (یعنی عذاب) کے لئے تم جلدی کر رہے ہو وہ میرے پاس نہیں ہے (ایسا) حکم الله ہی کے اختیار میں ہے وہ سچی بات بیان فرماتا ہے اور وہ سب سے بہتر فیصلہ کرنے والا ہے","hi":"आप कह दें कि मैं अपने पालनहार की ओर से एक स्पष्ट प्रमाण पर क़ायम हूँ और तुमने उसे झुठला दिया है। मेरे पास वह चीज़ नहीं है जिसके लिए तुम जल्दी मचा रहे हो। निर्णय अल्लाह के सिवा किसी के अधिकार में नहीं। वह सत्य का वर्णन करता है और वही निर्णय करने वालों में सबसे बेहतर है।"},{"a":58,"ar":"قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ ۗ وَٱللَّهُ أَعْلَمُ بِٱلظَّـٰلِمِينَ","en":"Say, \"If I had that for which you are impatient, the matter would have been decided between me and you, but Allāh is most knowing of the wrongdoers.\"","ur":"کہہ دو کہ جس چیز کے لئے تم جلدی کر رہے ہو اگر وہ میرے اختیار میں ہوتی تو مجھ میں اور تم میں فیصلہ ہوچکا ہوتا۔ اور خدا ظالموں سے خوب واقف ہے","hi":"आप कह दें : यदि वाक़ई मेरे पास वह चीज़ होती जो तुम जल्दी माँग रहे हो, तो हमारे और तुम्हारे बीच मामले का निर्णय अवश्य कर दिया जाता तथा अल्लाह अत्याचारियों को अधिक जानने वाला है।"},{"a":59,"ar":"۞ وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ ۚ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ ۚ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَـٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ","en":"And with Him are the keys of the unseen; none knows them except Him. And He knows what is on the land and in the sea. Not a leaf falls but that He knows it. And no grain is there within the darknesses of the earth and no moist or dry [thing] but that it is [written] in a clear record.","ur":"اور اسی کے پاس غیب کی کنجیاں ہیں جن کو اس کے سوا کوئی نہیں جانتا۔ اور اسے جنگلوں اور دریاؤں کی سب چیزوں کا علم ہے۔ اور کوئی پتہ نہیں جھڑتا مگر وہ اس کو جانتا ہے اور زمین کے اندھیروں میں کوئی دانہ اور کوئی ہری اور سوکھی چیز نہیں ہے مگر کتاب روشن میں (لکھی ہوئی) ہے","hi":"और उसी (अल्लाह) के पास ग़ैब (परोक्ष) की कुंजियाँ हैं, उन्हें उसके सिवा कोई नहीं जानता। तथा वह जानता है जो कुछ थल और जल में है और कोई पत्ता नहीं गिरता, परंतु वह उसे जानता है। और धरती के अँधेरों में कोई दाना नहीं और न कोई गीली चीज़ है और न कोई सूखी चीज़, परंतु वह एक स्पष्ट पुस्तक में (अंकित) है।"},{"a":60,"ar":"وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ۖ ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ","en":"And it is He who takes your souls by night and knows what you have committed by day. Then He revives you therein [i.e., by day] that a specified term may be fulfilled. Then to Him will be your return; then He will inform you about what you used to do.","ur":"اور وہی تو ہے جو رات کو (سونے کی حالت میں) تمہاری روح قبض کرلیتا ہے اور جو کچھ تم دن میں کرتے ہو اس سے خبر رکھتا ہے پھر تمہیں دن کو اٹھا دیتا ہے تاکہ (یہی سلسلہ جاری رکھ کر زندگی کی) معین مدت پوری کردی جائے پھر تم (سب) کو اسی کی طرف لوٹ کر جانا ہے (اس روز) وہ تم کو تمہارے عمل جو تم کرتے ہو (ایک ایک کرکے) بتائے گا","hi":"और वही है, जो रात को तुम्हारी रूह़ क़ब्ज़ कर लेता है तथा जानता है जो कुछ तुमने दिन में कमाया। फिर वह तुम्हें उस (दिन) में उठा देता है, ताकि निर्धारित अवधि पूरी की जाए। फिर उसी की ओर तुम्हारा लौटना है, फिर वह तुम्हें बताएगा जो कुछ तुम किया करते थे।"},{"a":61,"ar":"وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۖ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ","en":"And He is the subjugator over His servants, and He sends over you guardian-angels until, when death comes to one of you, Our messengers [i.e., angels of death] take him, and they do not fail [in their duties].","ur":"اور وہ اپنے بندوں پر غالب ہے۔ اور تم پر نگہبان مقرر کئے رکھتا ہے۔ یہاں تک کہ جب تم میں سے کسی کی موت آتی ہے تو ہمارے فرشتے اس کی روح قبض کرلیتے ہیں اور وہ کسی طرح کی کوتاہی نہیں کرتے","hi":"तथा वही अपने बंदों पर ग़ालिब (हावी) है और वह तुमपर रक्षकों को भेजता है। यहाँ तक कि जब तुममें से किसी को मौत आती है, तो हमारे फ़रिश्ते उसका प्राण निकाल लेते हैं और वे कोताही नहीं करते।"},{"a":62,"ar":"ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۚ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَـٰسِبِينَ","en":"Then they [i.e., His servants] are returned to Allāh, their true Lord. Unquestionably, His is the judgement, and He is the swiftest of accountants.","ur":"پھر (قیامت کے دن تمام) لوگ اپنے مالک برحق خدا تعالیٰ کے پاس واپس بلائے جائیں گے۔ سن لو کہ حکم اسی کا ہے اور وہ نہایت جلد حساب لینے والا ہے","hi":"फिर वे अल्लाह की ओर लौटाए जाएँगे, जो उनका वास्तविक स्वामी है। सावधान! उसी को निर्णय करने का अधिकार है और वही सब हिसाब लेने वालों से अधिक शीध्र हिसाब लेने वाला है।"},{"a":63,"ar":"قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ","en":"Say, \"Who rescues you from the darknesses of the land and sea [when] you call upon Him imploring [aloud] and privately, 'If He should save us from this [crisis], we will surely be among the thankful.'\"","ur":"کہو بھلا تم کو جنگلوں اور دریاؤں کے اندھیروں سے کون مخلصی دیتا ہے (جب) کہ تم اسے عاجزی اور نیاز پنہانی سے پکارتے ہو (اور کہتے ہو) اگر خدا ہم کو اس (تنگی) سے نجات بخشے تو ہم اس کے بہت شکر گزار ہوں","hi":"(ऐ नबी!) उनसे पूछिए कि थल तथा जल के अँधेरों में तुम्हें कौन बचाता है? तुम उसे गिड़गिड़ाकर और चुपके-चुपके पुकारते हो कि निःसंदेह यदि वह हमें इससे बचा ले, तो हम अवश्य शुक्र करने वालों में से हो जाएँगे?"},{"a":64,"ar":"قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ","en":"Say, \"It is Allāh who saves you from it and from every distress; then you [still] associate others with Him.\"","ur":"کہو کہ خدا ہی تم کو اس (تنگی) سے اور ہر سختی سے نجات بخشتا ہے۔ پھر (تم) اس کے ساتھ شرک کرتے ہو","hi":"आप कह दें : अल्लाह ही तुम्हें इससे तथा प्रत्येक संकट से बचाता है। फिर (भी) तुम उसका साझी बनाते हो!"},{"a":65,"ar":"قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَـٰتِ لَعَلَّهُمْ يَفْقَهُونَ","en":"Say, \"He is the [one] Able to send upon you affliction from above you or from beneath your feet or to confuse you [so you become] sects and make you taste the violence of one another.\" Look how We diversify the signs that they might understand.","ur":"کہہ دو کہ وہ (اس پر بھی) قدرت رکھتا ہے کہ تم پر اوپر کی طرف سے یا تمہارے پاؤں کے نیچے سے عذاب بھیجے یا تمہیں فرقہ فرقہ کردے اور ایک کو دوسرے (سے لڑا کر آپس) کی لڑائی کا مزہ چکھادے۔ دیکھو ہم اپنی آیتوں کو کس کس طرح بیان کرتے ہیں تاکہ یہ لوگ سمجھیں","hi":"आप (उनसे) कह दें : वही इसका सामर्थ्य रखता है कि तुमपर तुम्हारे ऊपर से यातना भेज दे, या तुम्हारे पैरों के नीचे से, या तुम्हें विभिन्न समूह बनाकर परस्पर भिड़ा दे और तुममें से कुछ को कुछ की लड़ाई (का स्वाद) चखा दे। देखिए, हम कैसे आयतों को विभिन्न प्रकार से बयान करते हैं, ताकि वे समझें।"},{"a":66,"ar":"وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ ۚ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ","en":"But your people have denied it while it is the truth. Say, \"I am not over you a manager [i.e., authority].\"","ur":"اور اس (قرآن) کو تمہاری قوم نے جھٹلایا حالانکہ وہ سراسر حق ہے۔ کہہ دو کہ میں تمہارا داروغہ نہیں ہوں","hi":"और (ऐ नबी!) आपकी जाति ने इस (क़ुरआन) को झुठला दिया, हालाँकि वह सत्य है।आप कह दें : मैं हरगिज़ तुमपर कोई निरीक्षक नहीं हूँ।"},{"a":67,"ar":"لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ ۚ وَسَوْفَ تَعْلَمُونَ","en":"For every news [i.e., happening] is a finality; and you are going to know.","ur":"ہر خبر کے لئے ایک وقت مقرر ہے اور تم کو عنقریب معلوم ہوجائے گا","hi":"प्रत्येक सूचना का एक समय नियत है और तुम शीघ्र ही जान लोगे।"},{"a":68,"ar":"وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَـٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ ۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَـٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ","en":"And when you see those who engage in [offensive] discourse concerning Our verses, then turn away from them until they enter into another conversation. And if Satan should cause you to forget, then do not remain after the reminder with the wrongdoing people.","ur":"اور جب تم ایسے لوگوں کو دیکھو جو ہماری آیتوں کے بارے میں بیہودہ بکواس کر رہے ہوں تو ان سے الگ ہوجاؤ یہاں تک کہ اور باتوں میں مصروف ہوجائیں۔ اور اگر (یہ بات) شیطان تمہیں بھلا دے تو یاد آنے پر ظالم لوگوں کے ساتھ نہ بیٹھو","hi":"और जब आप उन लोगों को देखें, जो हमारी आयतों के विषय में (उपहास के साथ) बात करते हैं, तो उनसे मुँह फेर लें, यहाँ तक कि वे उसके अलावा बात में लग जाएँ, और यदि कभी शैतान आपको भुला दे, तो याद आ जाने के बाद ऐसे अत्याचारी लोगों के साथ न बैठें।"},{"a":69,"ar":"وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَـٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ","en":"And those who fear Allāh are not held accountable for them [i.e., the disbelievers] at all, but [only for] a reminder - that perhaps they will fear Him.","ur":"اور پرہیزگاروں پر ان لوگوں کے حساب کی کچھ بھی جواب دہی نہیں ہاں نصیحت تاکہ وہ بھی پرہیزگار ہوں","hi":"तथा उन लोगों पर जो अल्लाह से डरते हैं, इनके हिसाब का कुछ भार नहीं है, परंतु याद दिलाना है, ताकि वे बच जाएँ।"},{"a":70,"ar":"وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ ۖ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ","en":"And leave those who take their religion as amusement and diversion and whom the worldly life has deluded. But remind with it [i.e., the Qur’ān], lest a soul be given up to destruction for what it earned; it will have other than Allāh no protector and no intercessor. And if it should offer every compensation, it would not be taken from it [i.e., that soul]. Those are the ones who are given to destruction for what they have earned. For them will be a drink of scalding water and a painful punishment because they used to disbelieve.","ur":"اور جن لوگوں نے اپنےدین کو کھیل اور تماشا بنا رکھا ہے اور دنیا کی زندگی نے ان کو دھوکے میں ڈال رکھا ہے ان سے کچھ کام نہ رکھو ہاں اس (قرآن) کے ذریعے سے نصیحت کرتے رہو تاکہ (قیامت کے دن) کوئی اپنے اعمال کی سزا میں ہلاکت میں نہ ڈالا جائے (اس روز) خدا کےسوا نہ تو کوئی اس کا دوست ہوگا اور نہ سفارش کرنے والا۔ اور اگر وہ ہر چیز (جو روئے زمین پر ہے بطور) معاوضہ دینا چاہے تو وہ اس سے قبول نہ ہو یہی لوگ ہیں کہ اپنے اعمال کے وبال میں ہلاکت میں ڈالے گئے ان کے لئے پینے کو کھولتا ہوا پانی اور دکھ دینے والا عذاب ہے اس لئے کہ کفر کرتے تھے","hi":"तथा आप उन लोगों को छोड़ दें, जिन्होंने अपने धर्म को खेल और मनोरंजन बना लिया और उन्हें सांसारिक जीवन ने धोखे में डाल रखा है। आप इस (क़ुरआन) के द्वारा उपदेश दें कि कहीं कोई प्राणी अपने कमाए हुए के बदले विनाश में न डाल दिया जाए, उसके लिए अल्लाह के सिवा कोई न कोई सहायक हो और न कोई सिफ़ारिश करने वाला। और यदि वह हर प्रकार की छुड़ौती दे, तो उससे न ली जाए। यही लोग हैं जो विनाश के हवाले किए गए, उसके बदले जो उन्होंने कमाया। उनके लिए पीने को खौलता हुआ पानी तथा दर्दनाक यातना है, इस कारण कि वे कुफ़्र करते थे।"},{"a":71,"ar":"قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَـٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَـٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۖ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَـٰلَمِينَ","en":"Say, \"Shall we invoke instead of Allāh that which neither benefits us nor harms us and be turned back on our heels after Allāh has guided us? [We would then be] like one whom the devils enticed [to wander] upon the earth confused, [while] he has companions inviting him to guidance, [calling], 'Come to us.'\" Say, \"Indeed, the guidance of Allāh is the [only] guidance; and we have been commanded to submit to the Lord of the worlds.","ur":"کہو۔ کیا ہم خدا کے سوا ایسی چیز کو پکاریں جو نہ ہمارا بھلا کرسکے نہ برا۔ اور جب ہم کو خدا نے سیدھا رستہ دکھا دیا تو (کیا) ہم الٹے پاؤں پھر جائیں؟ (پھر ہماری ایسی مثال ہو) جیسے کسی کو جنات نے جنگل میں بھلا دیا ہو (اور وہ) حیران (ہو رہا ہو) اور اس کے کچھ رفیق ہوں جو اس کو رستے کی طرف بلائیں کہ ہمارے پاس چلا آ۔ کہہ دو کہ رستہ تو وہی ہے جو خدا نے بتایا ہے۔ اور ہمیں تو یہ حکم ملا ہے کہ ہم خدائے رب العالمین کے فرمانبردار ہوں","hi":"(ऐ नबी!) कह दीजिए : क्या हम अल्लाह के सिवा उसको पुकारें, जो न हमें लाभ पहुँचा सके और न हमें हानि पहुँचा सके और हम अपनी एड़ियों पर फेर दिए जाएँ, इसके बाद कि अल्लाह ने हमें मार्गदर्शन प्रदान किया है, उस व्यक्ति की तरह जिसे शैतानों ने धरती में बहका दिया, इस हाल में कि चकित है, उसके कुछ साथी हैं जो उसे सीधे मार्ग की ओर बुला रहे हैं कि हमारे पास चला आ। आप कह दें कि निःसंदेह अल्लाह का दर्शाया हुआ मार्ग ही असल मार्ग है और हमें आदेश दिया गया है कि हम सारे संसारों के पालनहार के आज्ञाकारी हो जाएँ।"},{"a":72,"ar":"وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ ۚ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ","en":"And to establish prayer and fear Him.\" And it is He to whom you will be gathered.","ur":"اور یہ (بھی) کہ نماز پڑھتے رہو اور اس سے ڈرتے رہو۔ اور وہی تو ہے جس کے پاس تم جمع کئے جاؤ گے","hi":"और यह कि नमाज़ स्थापित करो और उस (अल्लाह) से डरो, तथा वही है, जिसकी ओर तुम इकट्ठे किए जाओगे।"},{"a":73,"ar":"وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ وَيَوْمَ يَقُولُ كُن فَيَكُونُ ۚ قَوْلُهُ ٱلْحَقُّ ۚ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ","en":"And it is He who created the heavens and earth in truth. And the day [i.e., whenever] He says, \"Be,\" and it is, His word is the truth. And His is the dominion [on] the Day the Horn is blown. [He is] Knower of the unseen and the witnessed; and He is the Wise, the Aware.","ur":"اور وہی تو ہے جس نے آسمانوں اور زمین کو تدبیر سے پیدا کیا ہے۔ اور جس دن وہ فرمائے گا کہ ہو جا تو (حشر برپا) ہوجائے گا ۔ اس کا ارشاد برحق ہے۔ اور جس دن صور پھونکا جائے گا (اس دن) اسی کی بادشاہت ہوگی۔ وہی پوشیدہ اور ظاہر (سب) کا جاننے والا ہے اور وہی دانا اور خبردار ہے","hi":"और वही है, जिसने आकाशों तथा धरती की रचना सत्य के साथ की और जिस दिन वह कहेगा \"हो जा\" तो वह हो जाएगा। उसकी बात सत्य है और उसी का राज्य होगा, जिस दिन सूर में फूँका जाएगा। वह परोक्ष तथा प्रत्यक्ष को जानने वाला है और वही पूर्ण हिकमत वाला, हर चीज़ की खबर रखने वाला है।"},{"a":74,"ar":"۞ وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً ۖ إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَـٰلٍ مُّبِينٍ","en":"And [mention, O Muḥammad], when Abraham said to his father Āzar, \"Do you take idols as deities? Indeed, I see you and your people to be in manifest error.\"","ur":"اور (وہ وقت بھی یاد کرنے کے لائق ہے) جب ابراہیم نے اپنے باپ آزر سے کہا کہ تم بتوں کو کیا معبود بناتے ہو۔ میں دیکھتا ہوں کہ تم اور تمہاری قوم صریح گمراہی میں ہو","hi":"तथा जब इबराहीम ने अपने पिता आज़र से कहा : क्या आप मूर्तियों को पूज्य बनाते हो? निःसंदेह मैं आपको तथा आपकी जाति को खुली पथभ्रष्टता में देखता हूँ।"},{"a":75,"ar":"وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ","en":"And thus did We show Abraham the realm of the heavens and the earth that he would be among the certain [in faith].","ur":"اور ہم اس طرح ابراہیم کو آسمانوں اور زمین کے عجائبات دکھانے لگے تاکہ وہ خوب یقین کرنے والوں میں ہوجائیں","hi":"और इसी प्रकार हम इबराहीम को आकाशों तथा धरती का महान राज्य दिखाते थे और ताकि वह परिपूर्ण विश्वास रखने वालों में से हो जाए।"},{"a":76,"ar":"فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا ۖ قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ","en":"So when the night covered him [with darkness], he saw a star. He said, \"This is my lord.\" But when it set, he said, \"I like not those that set [i.e., disappear].\"","ur":"(یعنی) جب رات نے ان کو (پردہٴ تاریکی سے) ڈھانپ لیا (تو آسمان میں) ایک ستارا نظر پڑا۔ کہنے لگے یہ میرا پروردگار ہے۔ جب وہ غائب ہوگیا تو کہنے لگے کہ مجھے غائب ہوجانے والے پسند نہیں","hi":"तो जब उसपर रात छा गई, तो उसने एक तारा देखा। कहने लगा : यह मेरा पालनहार है। फिर जब वह डूब गया, तो उसने कहा : मैं डूबने वालों से प्रेम नहीं करता।"},{"a":77,"ar":"فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ","en":"And when he saw the moon rising, he said, \"This is my lord.\" But when it set, he said, \"Unless my Lord guides me, I will surely be among the people gone astray.\"","ur":"پھر جب چاند کو دیکھا کہ چمک رہا ہے تو کہنے لگے یہ میرا پروردگار ہے۔ لیکن جب وہ بھی چھپ گیا تو بول اٹھے کہ میرا پروردگار مجھے سیدھا رستہ نہیں دکھائے گا تو میں ان لوگوں میں ہوجاؤں گا جو بھٹک رہے ہیں","hi":"फिर जब उसने चाँद को चमकता हुआ देखा, तो कहा : यह मेरा पालनहार है। फिर जब वह डूब गया, तो उसने कहा : निःसंदेह यदि मेरे पालनहार ने मुझे मार्ग नहीं दिखाया, तो निश्चय मैं अवश्य पथभ्रष्ट लोगों में से हो जाऊँगा।"},{"a":78,"ar":"فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَـٰذَا رَبِّى هَـٰذَآ أَكْبَرُ ۖ فَلَمَّآ أَفَلَتْ قَالَ يَـٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ","en":"And when he saw the sun rising, he said, \"This is my lord; this is greater.\" But when it set, he said, \"O my people, indeed I am free from what you associate with Allāh.","ur":"پھر جب سورج کو دیکھا کہ جگمگا رہا ہے تو کہنے لگے میرا پروردگار یہ ہے یہ سب سے بڑا ہے۔ مگر جب وہ بھی غروب ہوگیا تو کہنے لگے لوگو! جن چیزوں کو تم (خدا کا) شریک بناتے ہو میں ان سے بیزار ہوں","hi":"फिर जब उसने सूर्य को चमकता हुआ देखा, तो कहा : यह मेरा पालनहार है। यह सबसे बड़ा है। फिर जब वह (भी) डूब गया, तो कहने लगे : ऐ मेरी जाति के लोगो! निःसंदेह मैं उससे बरी हूँ, जो तुम (अल्लाह के साथ) साझी बनाते हो।"},{"a":79,"ar":"إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا ۖ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ","en":"Indeed, I have turned my face [i.e., self] toward He who created the heavens and the earth, inclining toward truth, and I am not of those who associate others with Allāh.\"","ur":"میں نے سب سے یکسو ہو کر اپنے تئیں اسی ذات کی طرف متوجہ کیا جس نے آسمانوں اور زمین کو پیدا کیا ہے اور میں مشرکوں میں سے نہیں ہوں","hi":"निःसंदेह मैंने एकाग्र होकर अपना चेहरा उसकी ओर कर लिया, जिसने आकाशों तथा धरती को पैदा किया है, और मैं मुश्रिकों में से नहीं हूँ।"},{"a":80,"ar":"وَحَآجَّهُۥ قَوْمُهُۥ ۚ قَالَ أَتُحَـٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ ۚ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا ۗ وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا ۗ أَفَلَا تَتَذَكَّرُونَ","en":"And his people argued with him. He said, \"Do you argue with me concerning Allāh while He has guided me? And I fear not what you associate with Him [and will not be harmed] unless my Lord should will something. My Lord encompasses all things in knowledge; then will you not remember?","ur":"اور ان کی قوم ان سے بحث کرنے لگی تو انہوں نے کہا کہ تم مجھ سے خدا کے بارےمیں (کیا) بحث کرتے ہو اس نے تو مجھے سیدھا رستہ دکھا دیا ہے۔ اور جن چیزوں کو تم اس کا شریک بناتے ہو میں ان سے نہیں ڈرتا۔ ہاں جو میرا پروردگار چاہے۔ میرا پروردگار اپنے علم سے ہر چیز پر احاطہ کئے ہوئے ہے۔ کیا تم خیال نہیں کرتے۔","hi":"और उसकी जाति ने उससे झगड़ा किया, उसने कहा : क्या तुम मुझसे अल्लाह के विषय में झगड़ते हो, हालाँकि निश्चय उसने मुझे मार्गदर्शन प्रदान किया है तथा मैं उससे नहीं डरता, जिसे तुम उसके साथ साझी बनाते हो। परंतु यह कि मेरा पालनहार कुछ चाहे। मेरे पालनहार ने प्रत्येक वस्तु को अपने ज्ञान से घेर रखा है। तो क्या तुम उपदेश ग्रहण नहीं करते?"},{"a":81,"ar":"وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَـٰنًا ۚ فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ ۖ إِن كُنتُمْ تَعْلَمُونَ","en":"And how should I fear what you associate while you do not fear that you have associated with Allāh that for which He has not sent down to you any authority? So which of the two parties has more right to security, if you should know?\"","ur":"بھلا میں ان چیزوں سے جن کو تم (خدا کا) شریک بناتے ہو کیونکرڈروں جب کہ تم اس سے نہیں ڈرتے کہ خدا کے ساتھ شریک بناتے ہو جس کی اس نے کوئی سند نازل نہیں کی۔ اب دونوں فریق میں سے کون سا فریق امن (اور جمعیت خاطر) کا مستحق ہے۔ اگر سمجھ رکھتے ہو (تو بتاؤ)","hi":"और मैं उससे कैसे डरूँ, जिसे तुमने साझी बनाया है, हालाँकि तुम इस बात से नहीं डरते कि निःसंदेह तुमने अल्लाह के साथ उसको साझी बनाया है, जिसकी कोई दलील उसने तुमपर नहीं उतारी, तो दोनों पक्षों में शांति का अधिक हक़दार कौन है, यदि तुम जानते हो?"},{"a":82,"ar":"ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَـٰنَهُم بِظُلْمٍ أُو۟لَـٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ","en":"They who believe and do not mix their belief with injustice - those will have security, and they are [rightly] guided.","ur":"جو لوگ ایمان لائے اور اپنے ایمان کو (شرک کے) ظلم سے مخلوط نہیں کیا ان کے امن (اور جمعیت خاطر) ہے اور وہی ہدایت پانے والے ہیں","hi":"जो लोग ईमान लाए और उन्होंने अपने ईमान को अत्याचार (शिर्क) के साथ नहीं मिलाया, यही लोग हैं जिनके लिए शांति है तथा वही मार्गदर्शन पाने वाले हैं।"},{"a":83,"ar":"وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَـٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ ۚ نَرْفَعُ دَرَجَـٰتٍ مَّن نَّشَآءُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ","en":"And that was Our [conclusive] argument which We gave Abraham against his people. We raise by degrees whom We will. Indeed, your Lord is Wise and Knowing.","ur":"اور یہ ہماری دلیل تھی جو ہم نے ابراہیم کو ان کی قوم کے مقابلے میں عطا کی تھی۔ ہم جس کے چاہتے ہیں درجے بلند کردیتے ہیں۔ بےشک تمہارا پروردگار دانا اور خبردار ہے","hi":"यह हमारा तर्क है, जो हमने इबराहीम को उसकी जाति के विरुद्ध प्रदान किया। हम जिसे चाहते है, पदों में ऊँचा कर देते हैं। निःसंदेह आपका पालनहार पूर्ण हिकमत वाला, सब कुछ जानने वाला है।"},{"a":84,"ar":"وَوَهَبْنَا لَهُۥٓ إِسْحَـٰقَ وَيَعْقُوبَ ۚ كُلًّا هَدَيْنَا ۚ وَنُوحًا هَدَيْنَا مِن قَبْلُ ۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَـٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَـٰرُونَ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","en":"And We gave to him [i.e., Abraham] Isaac and Jacob - all [of them] We guided. And Noah, We guided before; and among his descendants, David and Solomon and Job and Joseph and Moses and Aaron. Thus do We reward the doers of good.","ur":"اور ہم نے ان کو اسحاق اور یعقوب بخشے۔ (اور) سب کو ہدایت دی۔ اور پہلے نوح کو بھی ہدایت دی تھی اور ان کی اولاد میں سے داؤد اور سلیمان اور ایوب اور یوسف اور موسیٰ اور ہارون کو بھی۔ اور ہم نیک لوگوں کو ایسا ہی بدلا دیا کرتے ہیں","hi":"और हमने उसे (इबराहीम को) इसहाक़ और याक़ूब प्रदान किए, प्रत्येक को हमने मार्गदर्शन दिया और उससे पहले नूह को मार्गदर्शन प्रदान किया और उसकी संतति में से दाऊद और सुलैमान और अय्यूब और यूसुफ़ और मूसा तथा हारून को। और इसी प्रकार हम नेकी करने वालों को प्रतिफल प्रदान करते हैं।"},{"a":85,"ar":"وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ ۖ كُلٌّ مِّنَ ٱلصَّـٰلِحِينَ","en":"And Zechariah and John and Jesus and Elias - and all were of the righteous.","ur":"اور زکریا اور یحییٰ اور عیسیٰ اور الیاس کو بھی۔ یہ سب نیکوکار تھے","hi":"तथा ज़करीया और यह़्या और ईसा और इलयास को। ये सभी सदाचारियों में से थे।"},{"a":86,"ar":"وَإِسْمَـٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا ۚ وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَـٰلَمِينَ","en":"And Ishmael and Elisha and Jonah and Lot - and all [of them] We preferred over the worlds.","ur":"اور اسمٰعیل اور الیسع اور یونس اور لوط کو بھی۔ اور ان سب کو جہان کے لوگوں پر فضلیت بخشی تھی","hi":"तथा इसमाईल और अल-यसअ, यूनुस और लूत को। और उन सबको हमने संसार वालों पर श्रेष्ठता प्रदान की है।"},{"a":87,"ar":"وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّـٰتِهِمْ وَإِخْوَٰنِهِمْ ۖ وَٱجْتَبَيْنَـٰهُمْ وَهَدَيْنَـٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ","en":"And [some] among their fathers and their descendants and their brothers - and We chose them and We guided them to a straight path.","ur":"اور بعض بعض کو ان کے باپ دادا اور اولاد اور بھائیوں میں سے بھی۔ اور ان کو برگزیدہ بھی کیا تھا اور سیدھا رستہ بھی دکھایا تھا","hi":"तथा उनके बाप-दादा और उनकी संतानों तथा उनके भाइयों में से भी कुछ को (तौफ़ीक़ दी) और हमने उन्हें चुन लिया और सीधे मार्ग की ओर उनका मार्गदर्शन किया।"},{"a":88,"ar":"ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ","en":"That is the guidance of Allāh by which He guides whomever He wills of His servants. But if they had associated others with Allāh, then worthless for them would be whatever they were doing.","ur":"یہ خدا کی ہدایت ہے اس پر اپنے بندوں میں سے جسے چاہے چلائے۔ اور اگر وہ لوگ شرک کرتے تو جو عمل وہ کرتے تھے سب ضائع ہوجاتے","hi":"यह अल्लाह का मार्गदर्शन है, जिसपर वह अपने बंदों में से जिसे चाहता है, चलाता है। और यदि ये लोग शिर्क करते, तो निश्चय उनसे वह सब नष्ट हो जाता जो वे किया करते थे।"},{"a":89,"ar":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ۚ فَإِن يَكْفُرْ بِهَا هَـٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَـٰفِرِينَ","en":"Those are the ones to whom We gave the Scripture and authority and prophethood. But if they [i.e., the disbelievers] deny it, then We have entrusted it to a people who are not therein disbelievers.","ur":"یہ وہ لوگ تھے جن کو ہم نے کتاب اور حکم (شریعت) اور نبوت عطا فرمائی تھی۔ اگر یہ (کفار) ان باتوں سے انکار کریں تو ہم نے ان پر (ایمان لانے کے لئے) ایسے لوگ مقرر کردیئے ہیں کہ وہ ان سے کبھی انکار کرنے والے نہیں","hi":"यही वे लोग हैं जिन्हें हमने पुस्तक, हिकमत एवं नुबुव्वत प्रदान की। फिर यदि ये (मुश्रिक) इन बातों का इनकार करें, तो हमने इन (बातों) के लिए ऐसे लोग नियत किए हैं, जो इनका इनकार करने वाले नहीं।"},{"a":90,"ar":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ ۖ فَبِهُدَىٰهُمُ ٱقْتَدِهْ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَـٰلَمِينَ","en":"Those are the ones whom Allāh has guided, so from their guidance take an example. Say, \"I ask of you for it [i.e., this message] no payment. It is not but a reminder for the worlds.\"","ur":"یہ وہ لوگ ہیں جن کو خدا نے ہدایت دی تھی تو تم انہیں کی ہدایت کی پیروی کرو۔ کہہ دو کہ میں تم سے اس (قرآن) کا صلہ نہیں مانگتا۔ یہ تو جہان کے لوگوں کے لئےمحض نصیحت ہے","hi":"यही वे लोग हैं, जिन्हें अल्लाह ने मार्गदर्शन प्रदान किया, तो आप उनके मार्गदर्शन का अनुसरण करें। आप कह दें : मैं इस (कार्य) पर तुमसे कोई बदला नहीं माँगता। यह तो सारे संसारों के लिए एक उपदेश के सिवा कुछ नहीं।"},{"a":91,"ar":"وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ ۗ قُلْ مَنْ أَنزَلَ ٱلْكِتَـٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ ۖ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا ۖ وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ ۖ قُلِ ٱللَّهُ ۖ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ","en":"And they did not appraise Allāh with true appraisal when they said, \"Allāh did not reveal to a human being anything.\" Say, \"Who revealed the Scripture that Moses brought as light and guidance to the people? You [Jews] make it into pages, disclosing [some of] it and concealing much. And you were taught that which you knew not - neither you nor your fathers.\" Say, \"Allāh [revealed it].\" Then leave them in their [empty] discourse, amusing themselves.","ur":"اور ان لوگوں نے خدا کی قدر جیسی جاننی چاہیئے تھی نہ جانی۔ جب انہوں نے کہا کہ خدا نے انسان پر (وحی اور کتاب وغیرہ) کچھ بھی نازل نہیں کیا۔ کہو جو کتاب موسیٰ لے کر آئے تھے اسے کس نے نازل کیا تھا جو لوگوں کے لئے نور اور ہدایت تھی اور جسے تم نے علیحدہ علیحدہ اوراق (پر نقل) کر رکھا ہے ان (کے کچھ حصے) کو تو ظاہر کرتے ہو اور اکثر کو چھپاتے ہو۔ اور تم کو وہ باتیں سکھائی گئیں جن کو نہ تم جانتے تھے اور نہ تمہارے باپ دادا۔ کہہ دو (اس کتاب کو) خدا ہی نے (نازل کیا تھا) پھر ان کو چھوڑ دیا کہ اپنی بیہودہ بکواس میں کھیلتے رہیں","hi":"तथा उन्होंने अल्लाह की महिमा नहीं की, जो उसकी महिमा का हक़ था, जब उन्होंने कहा कि अल्लाह ने किसी मनुष्य पर कोई चीज़ नहीं उतारी। कहो : वह पुस्तक किसने उतारी, जो मूसा लेकर आए? जो लोगों के लिए प्रकाश तथा मार्गदर्शन थी, तुम उसे पन्नों में करके रखते हो, जिन्हें तुम प्रकट करते हो और बहुत-से छिपाते हो, तथा तुम्हें वह ज्ञान दिया गया, जिसे न तुम जानते थे और न तुम्हारे बाप-दादा। आप कह दें कि अल्लाह ने। फिर उन्हें छोड़ दें अपनी व्यर्थ की चर्चा में खेलते रहें।"},{"a":92,"ar":"وَهَـٰذَا كِتَـٰبٌ أَنزَلْنَـٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا ۚ وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ يُؤْمِنُونَ بِهِۦ ۖ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ","en":"And this is a Book which We have sent down, blessed and confirming what was before it, that you may warn the Mother of Cities [i.e., Makkah] and those around it. Those who believe in the Hereafter believe in it, and they are maintaining their prayers.","ur":"اور (ویسی ہی) یہ کتاب ہے جسے ہم نے نازل کیا ہے بابرکت جو اپنے سے پہلی (کتابوں) کی تصدیق کرتی ہے اور (جو) اس لئے (نازل کی گئی ہے) کہ تم مکے اور اس کے آس پاس کے لوگوں کو آگاہ کردو۔ اور جو لوگ آخرت پر ایمان رکھتے ہیں وہ اس کتاب پر بھی ایمان رکھتے ہیں اور وہ اپنی نمازوں کی پوری خبر رکھتے ہیں","hi":"तथा यह (क़ुरआन) एक पुस्तक है, जिसे हमने उतारा है, बड़ी बरकत वाली है, उसकी पुष्टि करने वाली है जो उससे पहले है, और ताकि आप बस्तियों के केंद्र (मक्का) तथा उसके चारों ओर के लोगों को डराएँ, तथा जो लोग आख़िरत पर ईमान रखते हैं, वे इसपर ईमान लाते हैं और वे अपनी नमाज़ों की रक्षा करते हैं।"},{"a":93,"ar":"وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ ۗ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَـٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ۖ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَـٰتِهِۦ تَسْتَكْبِرُونَ","en":"And who is more unjust than one who invents a lie about Allāh or says, \"It has been inspired to me,\" while nothing has been inspired to him, and one who says, \"I will reveal [something] like what Allāh revealed.\" And if you could but see when the wrongdoers are in the overwhelming pangs of death while the angels extend their hands, [saying], \"Discharge your souls! Today you will be awarded the punishment of [extreme] humiliation for what you used to say against Allāh other than the truth and [that] you were, toward His verses, being arrogant.\"","ur":"اور اس سے بڑھ کر ظالم کون ہوگا جو خدا پر جھوٹ افتراء کرے۔ یا یہ کہے کہ مجھ پر وحی آئی ہے حالانکہ اس پر کچھ بھی وحی نہ آئی ہو اور جو یہ کہے کہ جس طرح کی کتاب خدا نے نازل کی ہے اس طرح کی میں بھی بنا لیتا ہوں۔ اور کاش تم ان ظالم (یعنی مشرک) لوگوں کو اس وقت دیکھو جب موت کی سختیوں میں (مبتلا) ہوں اور فرشتے (ان کی طرف عذاب کے لئے) ہاتھ بڑھا رہے ہوں کہ نکالو اپنی جانیں۔ آج تم کو ذلت کے عذاب کی سزا دی جائے گی اس لئے کہ تم خدا پر جھوٹ بولا کرتے تھے اور اس کی آیتوں سے سرکشی کرتے تھے","hi":"और उससे बढ़कर अत्याचारी कौन है, जो अल्लाह पर झूठ गढ़े, या कहे कि मेरी ओर वह़्य (प्रकाशना) की गई है, हालाँकि उसकी ओर कोई चीज़ वह़्य (प्रकाशना) नहीं की गई तथा जो कहे कि अल्लाह ने जो उतारा है, उसके समान मैं (भी) उतार दूँगा। और काश! (ऐ नबी!) आप देखें जब अत्याचारी लोग मौत की कठिनाइयों में होते हैं और फ़रिश्ते अपने हाथ फैलाए हुए होते हैं, (कहते हैं) : निकालो अपने प्राण! आज तुम्हें अपमानजनक यातना दी जाएगी, इस कारण कि तुम अल्लाह पर अनुचित (झूठ) बातें कहते थे और तुम उसकी आयतों (को मानने) से अभिमान करते थे।"},{"a":94,"ar":"وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَـٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَـٰكُمْ وَرَآءَ ظُهُورِكُمْ ۖ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَـٰٓؤُا۟ ۚ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ","en":"[It will be said to them], \"And you have certainly come to Us alone [i.e., individually] as We created you the first time, and you have left whatever We bestowed upon you behind you. And We do not see with you your 'intercessors' which you claimed that they were among you associates [of Allāh]. It has [all] been severed between you, and lost from you is what you used to claim.\"","ur":"اور جیسا ہم نے تم کو پہلی دفعہ پیدا کیا تھا ایسا ہی آج اکیلے اکیلے ہمارے پاس آئے اور جو (مال ومتاع) ہم نے تمہیں عطا فرمایا تھا وہ سب اپنی پیٹھ پیچھے چھوڑ آئے اور ہم تمہارے ساتھ تمہارے سفارشیوں کو بھی نہیں دیکھتے جن کی نسبت تم خیال کرتے تھے کہ وہ تمہارے (شفیع اور ہمارے) شریک ہیں۔ (آج) تمہارے آپس کے سب تعلقات منقطع ہوگئے اور جو دعوے تم کیا کرتے تھے سب جاتے رہے","hi":"तथा निःसंदेह तुम हमारे पास अकेले-अकेले आए हो, जैसे हमने तुम्हें प्रथम बार पैदा किया था, तथा हमने जो कुछ तु्म्हें दिया था, अपनी पीठों के पीछे छोड़ आए हो और हम तुम्हारे साथ तुम्हारे उन सिफ़ारिशियों को नहीं देखते, जिनके बारे में तुम्हारा भ्रम था कि निःसंदेह वे तुम्हारे कामों में (अल्लाह के) साझी हैं? निश्चय तुम्हारे बीच का संबंध कट गया और तुमसे गुम हो गया, जो कुछ तुम गुमान किया करते थे।"},{"a":95,"ar":"۞ إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ ۖ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ۚ ذَٰلِكُمُ ٱللَّهُ ۖ فَأَنَّىٰ تُؤْفَكُونَ","en":"Indeed, Allāh is the cleaver of grain and date seeds. He brings the living out of the dead and brings the dead out of the living. That is Allāh; so how are you deluded?","ur":"بے شک خدا ہی دانے اور گٹھلی کو پھاڑ کر (ان سے درخت وغیرہ) اگاتا ہے وہی جاندار کو بے جان سے نکالتا ہے اور وہی بےجان کا جاندار سے نکالنے والا ہے۔ یہی تو خدا ہے۔ پھر تم کہاں بہکے پھرتے ہو","hi":"निःसंदेह अल्लाह ही दाने तथा गुठलियों को फाड़ने वाला है। वह सजीव को निर्जीव से निकालता है तथा निर्जीव को सजीव से निकालने वाला है। यही अल्लाह है, फिर तुम कहाँ बहकाए जाते हो?"},{"a":96,"ar":"فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ","en":"[He is] the cleaver of daybreak and has made the night for rest and the sun and moon for calculation. That is the determination of the Exalted in Might, the Knowing.","ur":"وہی (رات کے اندھیرے سے) صبح کی روشنی پھاڑ نکالتا ہے اور اسی نے رات کو (موجب) آرام (ٹھہرایا) اور سورج اور چاند کو (ذرائع) شمار بنایا ہے۔ یہ خدا کے (مقرر کئے ہوئے) اندازے ہیں جو غالب (اور) علم والا ہے","hi":"(वही) पौ फाड़ने वाला है और उसी ने रात को आराम के लिए तथा सूर्य और चाँद को हिसाब का साधन बनाया। यह अति प्रभुत्वशाली, सब कुछ जानने वाले का ठहराया हुआ अंदाज़ा है।"},{"a":97,"ar":"وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ","en":"And it is He who placed for you the stars that you may be guided by them through the darknesses of the land and sea. We have detailed the signs for a people who know.","ur":"اور وہی تو ہے جس نے تمہارے لئے ستارے بنائے تاکہ جنگلوں اور دریاؤں کے اندھیروں میں ان سے رستے معلوم کرو۔ عقل والوں کے لئے ہم نے اپنی آیتیں کھول کھول کر بیان کردی ہیں","hi":"तथा वही है जिसने तुम्हारे लिए तारे बनाए, ताकि तुम उनके द्वारा थल और समुद्र के अँधेरों में मार्ग पा सको। निःसंदेह हमने उन लोगों के लिए खोलकर निशानियाँ बयान कर दी हैं, जो ज्ञान रखते हैं।"},{"a":98,"ar":"وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَفْقَهُونَ","en":"And it is He who produced you from one soul and [gave you] a place of dwelling and of storage. We have detailed the signs for a people who understand.","ur":"اور وہی تو ہے جس نے تم کو ایک شخص سے پیدا کیا۔ پھر (تمہارے لئے) ایک ٹھہرنے کی جگہ ہے اور ایک سپرد ہونے کی سمجھنے والوں کے لئے ہم نے (اپنی) آیتیں کھول کھول کر بیان کردی ہیں","hi":"वही है, जिसने तुम्हें एक जान से पैदा किया। फिर एक ठहरने का स्थान और एक सौंपे जाने का स्थान है। निःसंदहे हमने उन लोगों के लिए निशानियाँ खोलकर बयान कर दी हैं, जो समझते हैं।"},{"a":99,"ar":"وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّـٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَـٰبِهٍ ۗ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ ۚ إِنَّ فِى ذَٰلِكُمْ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ","en":"And it is He who sends down rain from the sky, and We produce thereby the growth of all things. We produce from it greenery from which We produce grains arranged in layers. And from the palm trees - of its emerging fruit are clusters hanging low. And [We produce] gardens of grapevines and olives and pomegranates, similar yet varied. Look at [each of] its fruit when it yields and [at] its ripening. Indeed in that are signs for a people who believe.","ur":"اور وہی تو ہے جو آسمان سے مینھ برساتا ہے۔ پھر ہم ہی (جو مینھ برساتے ہیں) اس سے ہر طرح کی روئیدگی اگاتے ہیں۔ پھر اس میں سے سبز سبز کونپلیں نکالتے ہیں۔ اور ان کونپلوں میں سے ایک دوسرے کے ساتھ جڑے ہوئے دانے نکالتے ہیں اور کھجور کے گابھے میں سے لٹکتے ہوئے گچھے اور انگوروں کے باغ اور زیتون اور انار جو ایک دوسرے سے ملتے جلتے بھی ہیں۔ اور نہیں بھی ملتے۔ یہ چیزیں جب پھلتی ہیں تو ان کے پھلوں پر اور (جب پکتی ہیں تو) ان کے پکنے پر نظر کرو۔ ان میں ان لوگوں کے لئے جو ایمان لاتے ہیں (قدرت خدا کی بہت سی) نشانیاں ہیں","hi":"तथा वही है जिसने आकाश से कुछ पानी उतारा, फिर हमने उसके द्वारा प्रत्येक प्रकार के पौधे निकाले। फिर हमने उससे हरियाली निकाली। जिसमें से हम तह-ब-तह चढ़े हुए दाने निकालते हैं तथा खजूर के पेड़ों से उनके गाभे से झुके हुए गुच्छे हैं तथा अंगूरों के बाग़ और ज़ैतून और अनार मिलते-जुलते और न मिलने-जुलने वाले। उसके फल को देखो, जब वह फल लाए तथा उसके पकने की ओर। निःसंदेह इनमें उन लोगों के लिए निश्चय बहुत-सी निशानियाँ हैं, जो ईमान लाते हैं।"},{"a":100,"ar":"وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ ۖ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَـٰتٍۭ بِغَيْرِ عِلْمٍ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يَصِفُونَ","en":"But they have attributed to Allāh partners - the jinn, while He has created them - and have fabricated for Him sons and daughters without knowledge. Exalted is He and high above what they describe.","ur":"اور ان لوگوں نے جنوں کو خدا کا شریک ٹھہرایا۔ حالانکہ ان کو اسی نے پیدا کیا اور بےسمجھے (جھوٹ بہتان) اس کے لئے بیٹے اور بیٹیاں بنا کھڑی کیں وہ ان باتوں سے جو اس کی نسبت بیان کرتے ہیں پاک ہے اور (اس کی شان ان سے) بلند ہے","hi":"और उन्होंने जिन्नों को अल्लाह का साझी बना दिया। हालाँकि उस (अल्लाह) ने उन्हें पैदा किया है, तथा बिना कुछ ज्ञान के उसके लिए बेटे और बेटियाँ गढ़ लीं। वह पवित्र तथा सर्वोच्च है, उन बातों से, जो वे बयान करते हैं।"},{"a":101,"ar":"بَدِيعُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَـٰحِبَةٌ ۖ وَخَلَقَ كُلَّ شَىْءٍ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ","en":"[He is] Originator of the heavens and the earth. How could He have a son when He does not have a companion [i.e., wife] and He created all things? And He is, of all things, Knowing.","ur":"(وہی) آسمانوں اور زمین کا پیدا کرنے والا (ہے)۔ اس کے اولاد کہاں سے ہو جب کہ اس کی بیوی ہی نہیں۔ اور اس نے ہر چیز کو پیدا کیا ہے۔ اور وہ ہر چیز سے باخبر ہے","hi":"वह आकाशों तथा धरती का अविष्कारक है, उसकी संतान कैसे होगी, जबकि उसकी कोई पत्नी नहीं? तथा उसी ने हर चीज़ पैदा की और वह प्रत्येक वस्तु को भली-भाँति जानने वाला है।"},{"a":102,"ar":"ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ خَـٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ","en":"That is Allāh, your Lord; there is no deity except Him, the Creator of all things, so worship Him. And He is Disposer of all things.","ur":"یہی (اوصاف رکھنے والا) خدا تمہارا پروردگار ہے۔ اس کے سوا کوئی معبود نہیں۔ (وہی) ہر چیز کا پیداکرنے والا (ہے) تو اسی کی عبادت کرو۔ اور وہ ہر چیز کا نگراں ہے","hi":"यही अल्लाह तुम्हारा पालनहार है, उसके सिवा कोई सच्चा पूज्य नहीं, हर चीज़ का स्रष्टा है। अतः तुम उसी की इबादत करो तथा वह हर चीज़ का निरीक्षक है।"},{"a":103,"ar":"لَّا تُدْرِكُهُ ٱلْأَبْصَـٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَـٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ","en":"Vision perceives Him not, but He perceives [all] vision; and He is the Subtle, the Aware.","ur":"(وہ ایسا ہے کہ) نگاہیں اس کا ادراک نہیں کرسکتیں اور وہ نگاہوں کا ادراک کرسکتا ہے اور وہ بھید جاننے والا خبردار ہے","hi":"उसे निगाहें नहीं पातीं और वह सब निगाहों को पाता है और वही अत्यंत सूक्ष्मदर्शी, सब ख़बर रखने वाला है।"},{"a":104,"ar":"قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ ۖ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ ۖ وَمَنْ عَمِىَ فَعَلَيْهَا ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ","en":"There has come to you enlightenment from your Lord. So whoever will see does so for [the benefit of] his soul, and whoever is blind [does harm] against it. And [say], \"I am not a guardian over you.\"","ur":"(اے محمدﷺ! ان سے کہہ دو کہ) تمہارے (پاس) پروردگار کی طرف سے (روشن) دلیلیں پہنچ چکی ہیں تو جس نے (ان کو آنکھ کھول کر) دیکھا اس نے اپنا بھلا کیا اور جو اندھا بنا رہا اس نے اپنے حق میں برا کیا۔ اور میں تمہارا نگہبان نہیں ہوں","hi":"निःसंदेह तुम्हारे पास तुम्हारे पालनहार की ओर से कई निशानियाँ आ चुकीं। फिर जिसने देख लिया, तो उसका लाभ उसी के लिए है और जो अंधा रहा, तो उसकी हानि उसी पर है और मैं तुमपर कोई संरक्षक नहीं।"},{"a":105,"ar":"وَكَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَـٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ","en":"And thus do We diversify the verses so they [i.e., the disbelievers] will say, \"You have studied,\" and so We may make it [i.e., the Qur’ān] clear for a people who know.","ur":"اور ہم اسی طرح اپنی آیتیں پھیر پھیر کر بیان کرتے ہیں تاکہ کافر یہ نہ کہیں کہ تم (یہ باتیں اہل کتاب سے) سیکھے ہوئے ہو اور تاکہ سمجھنے والے لوگوں کے لئے تشریح کردیں","hi":"और इसी प्रकार, हम आयतों को विविध ढंग से बयान करते हैं और ताकि वे (मुश्रिक) कहें : आपने पढ़ा है, और ताकि हम उसे उन लोगों के लिए उजागर कर दें, जो ज्ञान रखते हैं।"},{"a":106,"ar":"ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ","en":"Follow, [O Muḥammad], what has been revealed to you from your Lord - there is no deity except Him - and turn away from those who associate others with Allāh.","ur":"اور جو حکم تمہارے پروردگار کی طرف سے تمہارے پاس آتا ہے اسی کی پیروی کرو۔ اس (پروردگار) کے سوا کوئی معبود نہیں۔ اور مشرکوں سے کنارہ کرلو","hi":"आप उसका पालन करें, जो आपकी ओर आपके पालनहार की तरफ़ से वह़्य की गई है, उसके सिवा कोई सत्य पूज्य नहीं और मुश्रिकों से किनारा कर लें।"},{"a":107,"ar":"وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ ۗ وَمَا جَعَلْنَـٰكَ عَلَيْهِمْ حَفِيظًا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ","en":"But if Allāh had willed, they would not have associated. And We have not appointed you over them as a guardian, nor are you a manager over them.","ur":"اور اگر خدا چاہتا تو یہ لوگ شرک نہ کرتے۔ اور (اے پیغمبر!) ہم نے تم کو ان پر نگہبان مقرر نہیں کیا۔ اور نہ تم ان کے داروغہ ہو","hi":"और यदि अल्लाह चाहता, तो वे लोग साझी न बनाते, तथा हमने आपको उनपर संरक्षक नहीं बनाया और न आप उनके कोई निरीक्षक हैं।"},{"a":108,"ar":"وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ ۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ","en":"And do not insult those they invoke other than Allāh, lest they insult Allāh in enmity without knowledge. Thus We have made pleasing to every community their deeds. Then to their Lord is their return, and He will inform them about what they used to do.","ur":"اور جن لوگوں کو یہ مشرک خدا کے سوا پکارتے ہیں ان کو برا نہ کہنا کہ یہ بھی کہیں خدا کو بےادبی سے بے سمجھے برا (نہ) کہہ بیٹھیں۔ اس طرح ہم نے ہر ایک فرقے کے اعمال (ان کی نظروں میں) اچھے کر دکھائے ہیں۔ پھر ان کو اپنے پروردگار ک طرف لوٹ کر جانا ہے تب وہ ان کو بتائے گا کہ وہ کیا کیا کرتے تھے","hi":"और (ऐ ईमान वालो!) उन्हें बुरा न कहो, जिन्हें ये (मुश्रिक) अल्लाह के सिवा पुकारते हैं। अन्यथा, वे अतिक्रम करते हुए अज्ञानतावश अल्लाह को बुरा कहेंगे। इसी प्रकार, हमने प्रत्येक समुदाय के लिए उनके कर्म को सुशोभित कर दिया है। फिर उनके पालनहार ही की ओर उनका लौटना है, तो वह उन्हें बताएगा, जो कुछ वे किया करते थे।"},{"a":109,"ar":"وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا ۚ قُلْ إِنَّمَا ٱلْـَٔايَـٰتُ عِندَ ٱللَّهِ ۖ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ","en":"And they swear by Allāh their strongest oaths that if a sign came to them, they would surely believe in it. Say, \"The signs are only with [i.e., from] Allāh.\" And what will make you perceive that even if it [i.e., a sign] came, they would not believe.","ur":"اور یہ لوگ خدا کی سخت سخت قسمیں کھاتے ہیں کہ اگر ان کے پاس کوئی نشانی آئے تو وہ اس پر ضروری ایمان لے آئیں۔ کہہ دو کہ نشانیاں تو سب خدا ہی کے پاس ہیں۔ اور (مومنو!) تمہیں کیا معلوم ہے (یہ تو ایسے بدبخت ہیں کہ ان کے پاس) نشانیاں آ بھی جائیں تب بھی ایمان نہ لائیں","hi":"और उन्होंने अपनी मज़बूत क़समें खाते हुए अल्लाह की क़सम खाई कि निःसंदेह यदि उनके पास कोई आयत (निशानी) आई, तो वे उसपर अवश्य ही ईमान लाएँगे। आप कह दें : आयतें (निशानियाँ) तो केवल अल्लाह के पास हैं और (ऐ ईमान वालो!) तुम्हें क्या पता कि निःसंदेह वे निशानियाँ जब आ जाएँगी, तो वे ईमान नहीं लाएँगे।"},{"a":110,"ar":"وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَـٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ","en":"And We will turn away their hearts and their eyes just as they refused to believe in it [i.e., the revelation] the first time. And We will leave them in their transgression, wandering blindly.","ur":"اور ہم ان کے دلوں اور آنکھوں کو الٹ دیں گے (تو) جیسے یہ اس (قرآن) پر پہلی دفعہ ایمان نہیں لائے (ویسے پھر نہ لائیں گے) اور ان کو چھوڑ دیں گے کہ اپنی سرکشی میں بہکتے رہیں","hi":"और हम उनके दिलों और उनकी आँखों को फेर देंगे, जैसे वे पहली बार इस (क़ुरआन) पर ईमान नहीं लाए और हम उन्हें छोड़ देंगे, अपनी सरकशी में भटकते फिरेंगे।"},{"a":111,"ar":"۞ وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَـٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَـٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ","en":"And even if We had sent down to them the angels [with the message] and the dead spoke to them [of it] and We gathered together every [created] thing in front of them, they would not believe unless Allāh should will. But most of them, [of that], are ignorant.","ur":"اور اگر ہم ان پر فرشتے بھی اتار دیتے اور مردے بھی ان سے گفتگو کرنے لگتے اور ہم سب چیزوں کو ان کے سامنے لا موجود بھی کر دیتے تو بھی یہ ایمان لانے والے نہ تھے اِلّا ماشائالله بات یہ ہے کہ یہ اکثر نادان ہیں","hi":"और यदि हम उनकी ओर फ़रिश्ते उतार देते और उनसे मुर्दे बातें करते और हम प्रत्येक चीज़ उनके सामने लाकर इकट्ठा कर देते, तो भी वे ऐसे न थे कि ईमान लाते, परंतु यह कि अल्लाह चाहे, लेकिन उनमें से अधिकतर लोग अज्ञानता से काम लेते हैं।"},{"a":112,"ar":"وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَـٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا ۚ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ","en":"And thus We have made for every prophet an enemy - devils from mankind and jinn, inspiring to one another decorative speech in delusion. But if your Lord had willed, they would not have done it, so leave them and that which they invent.","ur":"اور اسی طرح ہم نے شیطان (سیرت) انسانوں اور جنوں کو ہر پیغمبر کا دشمن بنا دیا تھا وہ دھوکا دینے کے لیے ایک دوسرے کے دل میں ملمع کی باتیں ڈالتے رہتے تھے اور اگر تمہارا پروردگار چاہتا تو وہ ایسا نہ کرتے تو ان کو اور جو کچھ یہ افتراء کرتے ہیں اسے چھوڑ دو","hi":"और (ऐ नबी!) इसी प्रकार, हमने हर नबी के लिए मनुष्यों एवं जिन्नों के शैतानों को शत्रु बना दिया, जो धोखा देने के लिए एक-दूसरे के मन में चिकनी-चुपड़ी बात डालते रहते हैं। और यदि आपका पालनहार चाहता, तो वे ऐसा न करते। तो आप उन्हें छोड़ दें और जो वे झूठ गढ़ते हैं।"},{"a":113,"ar":"وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ","en":"And [it is] so the hearts of those who disbelieve in the Hereafter will incline toward it [i.e., deceptive speech] and that they will be satisfied with it and that they will commit that which they are committing.","ur":"اور (وہ ایسے کام) اس لیے بھی (کرتے تھے) کہ جو لوگ آخرت پر ایمان نہیں رکھتے ان کے دل ان کی باتوں پر مائل ہوں اور وہ انہیں پسند کریں اور جو کام وہ کرتے تھے وہ ہی کرنے لگیں","hi":"और ताकि उन लोगों के दिल उस (सुशोभित झूठ) की ओर झुक जाएँ, जो आख़िरत पर विश्वास नहीं रखते और ताकि वे उसे पसंद करें और ताकि वे भी वही कुकर्म करने लगें, जो ये करने वाले हैं।"},{"a":114,"ar":"أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَـٰبَ مُفَصَّلًا ۚ وَٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ","en":"[Say], \"Then is it other than Allāh I should seek as judge while it is He who has revealed to you the Book [i.e., the Qur’ān] explained in detail?\" And those to whom We [previously] gave the Scripture know that it is sent down from your Lord in truth, so never be among the doubters.","ur":"(کہو) کیا میں خدا کے سوا اور منصف تلاش کروں حالانکہ اس نے تمہاری طرف واضع المطالب کتاب بھیجی ہے اور جن لوگوں کو ہم نے کتاب (تورات) دی ہے وہ جانتے ہیں کہ وہ تمہارے پروردگار کی طرف سے برحق نازل ہوئی ہے تو تم ہرگز شک کرنے والوں میں نہ ہونا","hi":"तो क्या मैं अल्लाह के सिवा कोई और न्यायकर्ता तलाश करूँ, हालाँकि उसी ने तुम्हारी ओर यह विस्तारपूर्ण पुस्तक उतारी है? तथा जिन लोगों को हमने पुस्तक प्रदान की है, वे जानते हैं कि निश्चय यह आपके पालनहार की ओर से सत्य के साथ अवतरित की गई है। अतः आप हरगिज़ संदेह करने वालों में से न हों।"},{"a":115,"ar":"وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا ۚ لَّا مُبَدِّلَ لِكَلِمَـٰتِهِۦ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","en":"And the word of your Lord has been fulfilled in truth and in justice. None can alter His words, and He is the Hearing, the Knowing.","ur":"اور تمہارے پروردگار کی باتیں سچائی اور انصاف میں پوری ہیں اس کی باتوں کو کوئی بدلنے والا نہیں اور وہ سنتا جانتا ہے","hi":"आपके पालनहार की बात सत्य एवं न्याय की दृष्टि से पूरी हो गई। उसकी बातों को कोई बदलने वाला नहीं। और वही सब कुछ सुनने वाला, सब कुछ जानने वाला है।"},{"a":116,"ar":"وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ","en":"And if you obey most of those upon the earth, they will mislead you from the way of Allāh. They follow not except assumption, and they are not but misjudging.","ur":"اور اکثر لوگ جو زمین پر آباد ہیں (گمراہ ہیں) اگر تم ان کا کہا مان لو گے تو وہ تمہیں خدا کا رستہ بھلا دیں گے یہ محض خیال کے پیچھے چلتے اور نرے اٹکل کے تیر چلاتے ہیں","hi":"और (ऐ नबी!) यदि आप उन लोगों में से अधिकतर का कहना मानें जो धरती पर हैं, तो वे आपको अल्लाह के मार्ग से भटका देंगे। वे तो केवल अनुमान का पालन करते हैं और वे इसके सिवा कुछ नहीं कि अटकल दौड़ाते हैं।"},{"a":117,"ar":"إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ","en":"Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of the [rightly] guided.","ur":"تمہارا پروردگار ان لوگوں کو خوب جانتا ہے جو اس کے رستے سے بھٹکے ہوئے ہیں اور ان سے بھی خوب واقف ہے جو رستے پر چل رہے ہیں","hi":"निःसंदेह आपका पालनहार ही उसे भली-भाँति जानने वाला है, जो उसके मार्ग से भटकता है तथा वही मार्गदर्शन पाने वालों को खूब जानने वाला है।"},{"a":118,"ar":"فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَـٰتِهِۦ مُؤْمِنِينَ","en":"So eat of that [meat] upon which the name of Allāh has been mentioned, if you are believers in His verses [i.e., revealed law].","ur":"تو جس چیز پر (ذبح کے وقت) خدا کا نام لیا جائے اگر تم اس کی آیتوں پر ایمان رکھتے ہو تو اسے کھا لیا کرو","hi":"तो तुम उसमें से खाओ, जिसपर (ज़बह करते समय) अल्लाह का नाम लिया गया है, यदि तुम उसकी आयतों पर ईमान रखने वाले हो।"},{"a":119,"ar":"وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ ۗ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ ۗ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ","en":"And why should you not eat of that upon which the name of Allāh has been mentioned while He has explained in detail to you what He has forbidden you, excepting that to which you are compelled. And indeed do many lead [others] astray through their [own] inclinations without knowledge. Indeed, your Lord - He is most knowing of the transgressors.","ur":"اور سبب کیا ہے کہ جس چیز پر خدا کا نام لیا جائے تم اسے نہ کھاؤ حالانکہ جو چیزیں اس نے تمہارے لیے حرام ٹھیرا دی ہیں وہ ایک ایک کر کے بیان کر دی ہیں (بے شک ان کو نہیں کھانا چاہیے) مگر اس صورت میں کہ ان کے (کھانے کے) لیے ناچار ہو جاؤ اور بہت سے لوگ بےسمجھے بوجھے اپنے نفس کی خواہشوں سے لوگوں کو بہکا رہے ہیں کچھ شک نہیں کہ ایسے لوگوں کو جو (خدا کی مقرر کی ہوئی) حد سے باہر نکل جاتے ہیں تمہارا پروردگار خوب جانتا ہے","hi":"और तुम्हें क्या है कि तुम उसमें से न खाओ, जिसपर अल्लाह का नाम लिया गया है, हालाँकि निःसंदेह उसने तुम्हारे लिए वे चीज़ें खोलकर बयान कर दी हैं, जो उसने तुमपर हराम की हैं, परंतु जिसकी ओर तुम विवश कर दिए जाओ। और निःसंदेह बहुत-से लोग बिना किसी जानकारी के, अपनी इच्छाओं के द्वारा (लोगों को) पथभ्रष्ट करते हैं। निःसंदेह आपका पालनहार ही हद से बढ़ने वालों को अधिक जानने वाला है।"},{"a":120,"ar":"وَذَرُوا۟ ظَـٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ ۚ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ","en":"And leave [i.e., desist from] what is apparent of sin and what is concealed thereof. Indeed, those who earn [blame for] sin will be recompensed for that which they used to commit.","ur":"اور ظاہری اور پوشیدہ (ہر طرح کا) گناہ ترک کر دو جو لوگ گناہ کرتے ہیں وہ عنقریب اپنے کئے کی سزا پائیں گے","hi":"तथा (ऐ लोगो!) खुले पाप छोड़ दो और उसके छिपे को भी। निःसंदेह जो लोग पाप कमाते हैं, वे शीघ्र ही उसका बदला दिए जाएँगे जो वे किया करते थे।"},{"a":121,"ar":"وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ ۗ وَإِنَّ ٱلشَّيَـٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَـٰدِلُوكُمْ ۖ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ","en":"And do not eat of that upon which the name of Allāh has not been mentioned, for indeed, it is grave disobedience. And indeed do the devils inspire their allies [among men] to dispute with you. And if you were to obey them, indeed, you would be associators [of others with Him].","ur":"اور جس چیز پر خدا کا نام نہ لیا جائے اسے مت کھاؤ کہ اس کا کھانا گناہ ہے اور شیطان (لوگ) اپنے رفیقوں کے دلوں میں یہ بات ڈالتے ہیں کہ تم سے جھگڑا کریں اور اگر تم لوگ ان کے کہے پر چلے تو بےشک تم بھی مشرک ہوئے","hi":"तथा उसमें से न खाओ, जिसपर अल्लाह का नाम न लिया गया हो, तथा निःसंदेह यह (खाना) सर्वथा अवज्ञा है। तथा निःसंदेह शैतान अपने मित्रों के मन में संशय डालते रहते हैं, ताकि वे तुमसे झगड़ा करें। और यदि तुमने उनका कहा मान लिया, तो निःसंदेह तुम निश्चय बहुदेववादी हो।"},{"a":122,"ar":"أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَـٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَـٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا ۚ كَذَٰلِكَ زُيِّنَ لِلْكَـٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ","en":"And is one who was dead and We gave him life and made for him light by which to walk among the people like one who is in darkness, never to emerge therefrom? Thus it has been made pleasing to the disbelievers that which they were doing.","ur":"بھلا جو پہلے مردہ تھا پھر ہم نے اس کو زندہ کیا اور اس کے لیے روشنی کر دی جس کے ذریعے سے وہ لوگوں میں چلتا پھرتا ہے کہیں اس شخص جیسا ہو سکتا ہے جو اندھیرے میں پڑا ہوا ہو اور اس سے نکل ہی نہ سکے اسی طرح کافر جو عمل کر رہے ہیں وہ انہیں اچھے معلوم ہوتے ہیں","hi":"क्या वह व्यक्ति जो मृत था, फिर हमने उसे जीवित किया तथा उसके लिए ऐसा प्रकाश बना दिया, जिसके साथ वह लोगों में चलता-फिरता है, उस व्यक्ति की तरह है जिसका हाल यह है कि वह अँधेरों में है, उनसे कदापि निकलने वाला नहीं? इसी प्रकार काफ़िरों के लिए वे कार्य सुंदर बना दिए गए, जो वे किया करते थे।"},{"a":123,"ar":"وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَـٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا ۖ وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ","en":"And thus We have placed within every city the greatest of its criminals to conspire therein. But they conspire not except against themselves, and they perceive [it] not.","ur":"اور اسی طرح ہم نے ہر بستی میں بڑے بڑے مجرم پیدا کئے کہ ان میں مکاریاں کرتے رہیں اور جو مکاریاں یہ کرتے ہیں ان کا نقصان انہیں کو ہے اور (اس سے) بےخبر ہیں","hi":"और इसी प्रकार हमने प्रत्येक बस्ती में सबसे बड़े उसके अपराधियों को बना दिया, ताकि वे उसमें चालें चलें। हालाँकि वे अपने ही विरुद्ध चालें चलते है, परंतु वे नहीं समझते।"},{"a":124,"ar":"وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ۘ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ ۗ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ","en":"And when a sign comes to them, they say, \"Never will we believe until we are given like that which was given to the messengers of Allāh.\" Allāh is most knowing of where [i.e., with whom] He places His message. There will afflict those who committed crimes debasement before Allāh and severe punishment for what they used to conspire.","ur":"اور جب ان کے پاس کوئی آیت آتی ہے تو کہتے ہیں کہ جس طرح کی رسالت خدا کے پیغمبروں کو ملی ہے جب تک اسی طرح کی رسالت ہم کو نہ ملے ہم ہرگز ایمان نہیں لائیں گے اس کو خدا ہی خوب جانتا ہے کہ (رسالت کا کون سا محل ہے اور) وہ اپنی پیغمبری کسے عنایت فرمائے جو لوگ جرم کرتے ہیں ان کو خدا کے ہاں ذلّت اور عذابِ شدید ہوگا اس لیے کہ مکّاریاں کرتے تھے","hi":"और जब उनके पास कोई निशानी आती है, तो कहते हैं कि हम कदापि ईमान नहीं लाएँगे, यहाँ तक कि हमें उस जैसा दिया जाए, जो अल्लाह के रसूलों को दिया गया। अल्लाह अधिक जानने वाला है जहाँ वह अपनी पैग़ंबरी रखता है। शीघ्र ही उन लोगों को जिन्होंने अपराध किए, अल्लाह के पास बड़े अपमान तथा कड़ी यातना का सामना करना पड़ेगा, इस कारण कि वे चालबाज़ी (छल) किया करते थे।"},{"a":125,"ar":"فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَـٰمِ ۖ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ ۚ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ","en":"So whoever Allāh wants to guide - He expands his breast to [contain] Islām; and whoever He wants to send astray - He makes his breast tight and constricted as though he were climbing into the sky. Thus does Allāh place defilement upon those who do not believe.","ur":"تو جس شخص کو خدا چاہتا ہے کہ ہدایت بخشے اس کا سینہ اسلام کے لیے کھول دیتا ہے اور جسے چاہتا ہے کہ گمراہ کرے اس کا سینہ تنگ اور گھٹا ہوا کر دیتا ہے گویا وہ آسمان پر چڑھ رہا ہے اس طرح خدا ان لوگوں پر جو ایمان نہیں لاتے عذاب بھیجتا ہے","hi":"तो वह व्यक्ति जिसे अल्लाह चाहता है कि उसे मार्गदर्शन प्रदान करे, उसका सीना इस्लाम के लिए खोल देता है और जिसे चाहता है कि उसे गुमराह करे, उसका सीना तंग, अत्यंत घुटा हुआ कर देता है, मानो वह बड़ी कठिनाई से आकाश में चढ़ रहा है। इसी प्रकार अल्लाह उन लोगों पर यातना भेज देता है, जो ईमान नहीं लाते।"},{"a":126,"ar":"وَهَـٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَذَّكَّرُونَ","en":"And this is the path of your Lord, [leading] straight. We have detailed the verses for a people who remember.","ur":"اور یہی تمہارے پروردگار کا سیدھا رستہ ہے جو لوگ غور کرنے والے ہیں ان کے لیے ہم نے اپنی آیتیں کھول کھول کر بیان کر دی ہیں","hi":"और यही आपके पालनहार का सीधा मार्ग है। निःसंदे हमने उन लोगों के लिए निशानियाँ खोलकर बयान कर दी हैं, जो उपदेश ग्रहण करते हों।"},{"a":127,"ar":"۞ لَهُمْ دَارُ ٱلسَّلَـٰمِ عِندَ رَبِّهِمْ ۖ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ","en":"For them will be the Home of Peace [i.e., Paradise] with their Lord. And He will be their protecting friend because of what they used to do.","ur":"ان کے لیے ان کے اعمال کے صلے میں پروردگار کے ہاں سلامتی کا گھر ہے اور وہی ان کا دوستدار ہے","hi":"उनके लिए उनके पालनहार के पास सलामती का घर है। और वह उनका संरक्षक है, उन कर्मों के कारण, जो वे करते थे।"},{"a":128,"ar":"وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَـٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ ۖ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا ۚ قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَـٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ","en":"And [mention, O Muḥammad], the Day when He will gather them together [and say], \"O company of jinn, you have [misled] many of mankind.\" And their allies among mankind will say, \"Our Lord, some of us made use of others, and we have [now] reached our term which You appointed for us.\" He will say, \"The Fire is your residence, wherein you will abide eternally, except for what Allāh wills. Indeed, your Lord is Wise and Knowing.\"","ur":"اور جس دن وہ سب (جنّ وانس) کو جمع کرے گا (اور فرمائے گا کہ) اے گروہ جنّات تم نے انسانوں سے بہت (فائدے) حاصل کئے تو جو انسانوں میں ان کے دوستدار ہوں گے وہ کہیں گے کہ پروردگار ہم ایک دوسرے سے فائدہ اٹھاتے رہے اور (آخر) اس وقت کو پہنچ گئے جو تو نے ہمارے لیے مقرر کیا تھا خدا فرمائے گا (اب) تمہارا ٹھکانہ دوزخ ہے ہمیشہ اس میں (جلتے) رہو گے مگر جو خدا چاہے بےشک تمہارا پروردگار دانا اور خبردار ہے","hi":"तथा (ऐ नबी! याद करें) जिस दिन अल्लाह उन सबको एकत्र करेगा, (फिर कहेगा :) ऐ जिन्नों के गिरोह! निःसंदेह तुमने बहुत-से मनुष्यों को गुमराह कर दिया है! और मनुष्यों में से उनके मित्र कहेंगे : ऐ हमारे पालनहार! हमने एक-दूसरे से लाभ उठाया और हम अपने उस समय को पहुँच गए, जो तूने हमारे लिए नियत किया था। (अल्लाह) कहेगा : आग ही तुम्हारा ठिकाना है, उसमें हमेशा रहने वाले हो, परंतु जो अल्लाह चाहे। निःसंदेह आपका पालनहार पूर्ण हिकमत वाला, सब कुछ जानने वाला है।"},{"a":129,"ar":"وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّـٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ","en":"And thus will We make some of the wrongdoers allies of others for what they used to earn.","ur":"اور اسی طرح ہم ظالموں کو ان کے اعمال کے سبب جو وہ کرتے تھے ایک دوسرے پر مسلط کر دیتے ہیں","hi":"और इसी प्रकार हम अत्याचारियों को एक-दूसरे का दोस्त बना देते हैं, उसके कारण जो वे कमाया करते थे।"},{"a":130,"ar":"يَـٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَـٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَا ۚ قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا ۖ وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ","en":"\"O company of jinn and mankind, did there not come to you messengers from among you, relating to you My verses and warning you of the meeting of this Day of yours?\" They will say, \"We bear witness against ourselves\"; and the worldly life had deluded them, and they will bear witness against themselves that they were disbelievers.","ur":"اے جنّوں اور انسانوں کی جماعت کیا تمہارے پاس تم ہی میں سے پیغمبر نہیں آتے رہے جو میری آیتیں تم کو پڑھ پڑھ کر سناتے اور اس دن کے سامنے آموجود ہونے سے ڈراتے تھے وہ کہیں گے کہ (پروردگار) ہمیں اپنے گناہوں کا اقرار ہے ان لوگوں کو دنیاکی زندگی نے دھوکے میں ڈال رکھا تھا اور (اب) خود اپنے اوپر گواہی دی کہ کفر کرتے تھے","hi":"(तथा अल्लाह कहेगा :) ऐ जिन्नों तथा मनुष्यों के समूह! क्या तुम्हारे पास तुममें से कोई रसूल नहीं आए, जो तुमपर मेरी आयतें बयान करते हों और तुम्हें तुम्हारे इस दिन की मुलाक़ात से डराते हों? वे कहेंगे : हम अपने आपपर गवाही देते हैं। तथा उन्हें सांसारिक जीवन ने धोखा दिया। और वे अपने आपपर गवाही देंगे कि निश्चय वे काफ़िर थे।"},{"a":131,"ar":"ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَـٰفِلُونَ","en":"That is because your Lord would not destroy the cities for wrongdoing while their people were unaware.","ur":"(اے محمدﷺ!) یہ (جو پیغمبر آتے رہے اور کتابیں نازل ہوتی رہیں تو) اس لیے کہ تمہارا پروردگار ایسا نہیں کہ بستیوں کو ظلم سے ہلاک کر دے اور وہاں کے رہنے والوں کو (کچھ بھی) خبر نہ ہو","hi":"(ऐ नबी!) यह (नबियों का भेजना) इसलिए हुआ कि आपका पालनहार किसी बस्ती वालों को - कुफ़्र - इनकार के कारण ऐसी अवस्था में विनष्ट नहीं करता कि उसके निवासी बेखबर हों।"},{"a":132,"ar":"وَلِكُلٍّ دَرَجَـٰتٌ مِّمَّا عَمِلُوا۟ ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا يَعْمَلُونَ","en":"And for all are degrees [i.e., positions resulting] from what they have done. And your Lord is not unaware of what they do.","ur":"اور سب لوگوں کے بلحاظ اعمال درجے (مقرر) ہیں اور جو کام یہ لوگ کرتے ہیں خدا ان سے بے خبر نہیں","hi":"तथा प्रत्येक व्यक्ति के लिए उसके कर्म के अनुसार पद हैं। और आपका पालनहार लोगों के कर्मों से अनभिज्ञ नहीं है।"},{"a":133,"ar":"وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ","en":"And your Lord is the Free of need, the possessor of mercy. If He wills, He can do away with you and give succession after you to whomever He wills, just as He produced you from the descendants of another people.","ur":"اور تمہارا پروردگار بےپروا (اور) صاحب رحمت ہے اگر چاہے (تو اے بندوں) تمہیں نابود کر دے اور تمہارے بعد جن لوگوں کو چاہے تمہارا جانشین بنا دے جیسا تم کو بھی دوسرے لوگوں کی نسل سے پیدا کیا ہے","hi":"तथा आपका पालनहार निस्पृह, दयाशील है। वह चाहे तो तुम्हें ले जाए और तुम्हारे स्थान पर दूसरों को ले आए। जैसे तुम लोगों को दूसरे लोगों की संतति से पैदा किया है।"},{"a":134,"ar":"إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ","en":"Indeed, what you are promised is coming, and you will not cause failure [to Allāh].","ur":"کچھ شک نہیں کہ جو وعدہ تم سے کیا جاتا ہے وہ (وقوع میں) آنے والا ہے اور تم (خدا کو) مغلوب نہیں کر سکتے","hi":"तुम्हें जिस (क़ियामत) का वचन दिया जा रहा है, उसे अवश्य आना है। और तुम (अल्लाह को) विवश नहीं कर सकते।"},{"a":135,"ar":"قُلْ يَـٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ ۖ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ","en":"Say, \"O my people, work according to your position; [for] indeed, I am working. And you are going to know who will have succession in the home. Indeed, the wrongdoers will not succeed.\"","ur":"کہہ دو کہ لوگو تم اپنی جگہ عمل کئے جاؤ میں (اپنی جگہ) عمل کئے جاتا ہوں عنقریب تم کو معلوم ہو جائے گا کہ آخرت میں (بہشت) کس کا گھر ہوگا کچھ شک نہیں کہ مشرک نجات نہیں پانے کے","hi":"(ऐ रसूल) आप कह दें : ऐ मेरी जाति के लोगो! (यदि तुम नहीं मानते) तो तुम अपनी जगह कर्म करते रहो। मैं भी कर्म कर रहा हूँ। शीघ्र ही तुम जान लोगे कि किसका अंत (परिणाम) अच्छा है। निःसंदेह अत्याचारी लोग सफल नहीं होंगे।"},{"a":136,"ar":"وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَـٰمِ نَصِيبًا فَقَالُوا۟ هَـٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَـٰذَا لِشُرَكَآئِنَا ۖ فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ ۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ ۗ سَآءَ مَا يَحْكُمُونَ","en":"And they [i.e., the polytheists] assign to Allāh from that which He created of crops and livestock a share and say, \"This is for Allāh,\" by their claim, \"and this is for our 'partners' [associated with Him].\" But what is for their \"partners\" does not reach Allāh, while what is for Allāh - this reaches their \"partners.\" Evil is that which they rule.","ur":"اور (یہ لوگ) خدا ہی کی پیدا کی ہوئی چیزوں یعنی کھیتی اور چوپایوں میں خدا کا بھی ایک حصہ مقرر کرتے ہیں اور اپنے خیال (باطل) سے کہتے ہیں کہ یہ (حصہ) تو خدا کا اور یہ ہمارے شریکوں (یعنی بتوں) کا تو جو حصہ ان کے شریکوں کا ہوتا ہے وہ تو خدا کی طرف نہیں جا سکتا اور جو حصہ خدا کا ہوتا ہے وہ ان کے شریکوں کی طرف جا سکتا ہے یہ کیسا برا انصاف ہے","hi":"तथा उन्होंने अल्लाह की पैदा की हुई खेती और पशुओं में उसका एक भाग निश्चित किया। फिर वे अपने विचार से कहते हैं : \"यह अल्लाह का है और यह हमारे ठहराए हुए साझीदारों का।\" फिर जो हिस्सा उनके बनाए हुए साझियों का है, वह तो अल्लाह को नहीं पहुँचता, परंतु जो हिस्सा अल्लाह का है, वह उनके साझियों को पहुँच जाता है। क्या ही बुरा निर्णय है, जो वे करते हैं!"},{"a":137,"ar":"وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَـٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ ۖ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ","en":"And likewise, to many of the polytheists their partners have made [to seem] pleasing the killing of their children in order to bring about their destruction and to cover them with confusion in their religion. And if Allāh had willed, they would not have done so. So leave them and that which they invent.","ur":"اسی طرح بہت سے مشرکوں کو ان کے شریکوں نے ان کے بچوں کو جان سے مار ڈالنا اچھا کر دکھایا ہے تاکہ انہیں ہلاکت میں ڈال دیں اور ان کے دین کو ان پر خلط ملط کر دیں اور اگر خدا چاہتا تو وہ ایسا نہ کرتے تو ان کو چھوڑ دو کہ وہ جانیں اور ان کا جھوٹ","hi":"और इसी प्रकार, बहुत-से मुश्रिकों के लिए, उनके बनाए हुए साझियों ने, उनकी अपनी संतान की हत्या को सुंदर बना दिया है, ताकि उनका विनाश कर दें और ताकि उनके धर्म को उनपर संदिग्ध कर दें। और यदि अल्लाह चाहता, तो वे ऐसा न करते। अतः आप उन्हें छोड़ दें तथा उनकी बनाई हुई बातों को।"},{"a":138,"ar":"وَقَالُوا۟ هَـٰذِهِۦٓ أَنْعَـٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَـٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَـٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ ۚ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ","en":"And they say, \"These animals and crops are forbidden; no one may eat from them except whom we will,\" by their claim. And there are those [camels] whose backs are forbidden [by them] and those upon which the name of Allāh is not mentioned - [all of this] an invention of untruth about Him. He will punish them for what they were inventing.","ur":"اور اپنے خیال سے یہ بھی کہتے ہیں کہ یہ چارپائے اور کھیتی منع ہے اسے اس شخص کے سوا جسے ہم چاہیں کوئی نہ کھائے اور (بعض) چارپائے ایسے ہیں کہ ان کی پیٹ پر چڑھنا منع کر دیا گیا ہے اور بعض مویشی ایسے ہیں جن پر (ذبح کرتے وقت) خدا کا نام نہیں لیتے سب خدا پر جھوٹ ہے وہ عنقریب ان کو ان کے جھوٹ کا بدلہ دے گا","hi":"तथा वे कहते हैं कि ये पशु और खेत वर्जित हैं। इन्हें वही खा सकता है, जिसे हम खिलाना चाहें। ऐसा वे अपने ख़याल से कहते हैं। फिर कुछ पशु हैं, जिनकी पीठ हराम (वर्जित) हैं। और कुछ पशु हैं, जिनपर (ज़बह करते समय) अल्लाह का नाम नहीं लेते। यह उन्होंने अल्लाह पर झूठ गढ़ा है। उन्हें वह उनके इस झूठ गढ़ने का बदला अवश्य देगा।"},{"a":139,"ar":"وَقَالُوا۟ مَا فِى بُطُونِ هَـٰذِهِ ٱلْأَنْعَـٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا ۖ وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ ۚ سَيَجْزِيهِمْ وَصْفَهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌ","en":"And they say, \"What is in the bellies of these animals is exclusively for our males and forbidden to our females. But if it is [born] dead, then all of them have shares therein.\" He will punish them for their description. Indeed, He is Wise and Knowing.","ur":"اور یہ بھی کہتے ہیں کہ جو بچہ ان چارپایوں کے پیٹ میں ہے وہ خاص ہمارے مردوں کے لئے ہے اور ہماری عورتوں کو (اس کا کھانا) حرام ہے اور اگر وہ بچہ مرا ہوا ہو تو سب اس میں شریک ہیں (یعنی اسے مرد اور عورتیں سب کھائیں) عنقریب خدا ان کو ان کے ڈھکوسلوں کی سزا دے گا بےشک وہ حکمت والا خبردار ہے","hi":"तथा उन्होंने कहा कि इन पशुओं के पेट में जो कुछ है, वह हमारे पुरुषों ही के लिए है और हमारी पत्नियों के लिए वर्जित है। और यदि मरा हुआ हो, तो सभी उसमें शामिल होंगे। शीघ्र ही अल्लाह उन्हें उनके ऐसा कहने का बदला देगा। निःसंदेह वह हिकमत वाला, सब कुछ जानने वाला है।"},{"a":140,"ar":"قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَـٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ ۚ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ","en":"They will have lost who killed their children in foolishness without knowledge and prohibited what Allāh had provided for them, inventing untruth about Allāh. They have gone astray and were not [rightly] guided.","ur":"جن لوگوں نے اپنی اولاد کو بیوقوفی سے بے سمجھی سے قتل کیا اور خدا پر افترا کر کے اس کی عطا فرمائی کی ہوئی روزی کو حرام ٹہرایا وہ گھاٹے میں پڑ گئے وہ بےشبہ گمراہ ہیں اور ہدایت یافتہ نہیں ہیں","hi":"निश्चय वे लोग क्षति में पड़ गए, जिन्होंने मूर्खता के कारण, बिना किसी ज्ञान के, अपने संतान की हत्या की। और उस जीविका को, जो अल्लाह ने उन्हें प्रदान की थी, अल्लाह पर आरोप लगाकर, अवैध बना लिया। वास्तव में, वे भटक गए और सीधी राह प्राप्त नहीं कर सके।"},{"a":141,"ar":"۞ وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّـٰتٍ مَّعْرُوشَـٰتٍ وَغَيْرَ مَعْرُوشَـٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَـٰبِهًا وَغَيْرَ مُتَشَـٰبِهٍ ۚ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ ۖ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ","en":"And He it is who causes gardens to grow, [both] trellised and untrellised, and palm trees and crops of different [kinds of] food and olives and pomegranates, similar and dissimilar. Eat of [each of] its fruit when it yields and give its due [zakāh] on the day of its harvest. And be not excessive. Indeed, He does not like those who commit excess.","ur":"اور خدا ہی تو ہے جس نے باغ پیدا کئے چھتریوں پر چڑھائے ہوئے بھی اور جو چھتریوں پر نہیں چڑھائے ہوئے وہ بھی اور کھجور اور کھیتی جن کے طرح طرح کے پھل ہوتے ہیں اور زیتون اور انار جو (بعض باتوں میں) ایک دوسرے سے ملتے ہیں جب یہ چیزیں پھلیں تو ان کے پھل کھاؤ اور جس دن (پھل توڑو اور کھیتی) کاٹو تو خدا کا حق بھی اس میں سے ادا کرو اور بےجا نہ اڑاؤ کہ خدا بیجا اڑانے والوں کو دوست نہیں رکھتا","hi":"अल्लाह वही है, जिसने बेलों वाले तथा बिना बेलों वाले बाग़ पैदा किए, तथा खजूर और खेती (पैदा की), जिनसे विभिन्न प्रकार की पैदावार प्राप्त होती है, और ज़ैतुन तथा अनार (पैदा किए), जो एक-दूसरे से मिलते-जुलते भी होते हैं और नहीं भी होते। जब वह फल दे, तो उसका फल खाओ और उकी कटाई के दिन उसका हक़ (ज़कात) अदा करो। और बेजा खर्च न करो। निःसंदेह अल्लाह बेजा ख़र्च करने वालों से प्रेम नहीं करता।"},{"a":142,"ar":"وَمِنَ ٱلْأَنْعَـٰمِ حَمُولَةً وَفَرْشًا ۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ","en":"And of the grazing livestock are carriers [of burdens] and those [too] small. Eat of what Allāh has provided for you and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.","ur":"اور چارپایوں میں بوجھ اٹھانے والے (یعنی بڑے بڑے) بھی پیدا کئے اور زمین سے لگے ہوئے (یعنی چھوٹے چھوٹے) بھی (پس) خدا کا دیا ہوا رزق کھاؤ اور شیطان کے قدموں پر نہ چلو وہ تمہارا صریح دشمن ہے","hi":"तथा चौपायों में कुछ सवारी और बोझ लादने योग्य (पैदा किए) और कुछ धरती से लगे हुए। जो कुछ अल्लाह ने तुम्हें दिया है, उसमें से खाओ और शैतान के पदचिह्नों पर न चलो। निश्चय ही वह तुम्हारा खुला शत्रु है।"},{"a":143,"ar":"ثَمَـٰنِيَةَ أَزْوَٰجٍ ۖ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَـٰدِقِينَ","en":"[They are] eight mates - of the sheep, two and of the goats, two. Say, \"Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Inform me with knowledge, if you should be truthful.\"","ur":"(یہ بڑے چھوٹے چارپائے) آٹھ قسم کے (ہیں) دو (دو) بھیڑوں میں سے اور دو (دو) بکریوں میں سے (یعنی ایک ایک نر اور اور ایک ایک مادہ) (اے پیغمبر ان سے) پوچھو کہ (خدا نے) دونوں (کے) نروں کو حرام کیا ہے یا دونوں (کی) مادنیوں کو یا جو بچہ مادنیوں کے پیٹ میں لپٹ رہا ہو اسے اگر سچے ہو تو مجھے سند سے بتاؤ","hi":"(अल्लाह ने) आठ नर-मादा (पैदा किए)। भेड़ में से दो और बकरी में से दो। आप उनसे पूछिए कि क्या अल्लाह ने दोनों नर हराम किए हैं अथवा दोनों मादा या उसे जो इन दोनों मादा के पेट में हो? मुझे किसी ज्ञान के आधार पर बताओ, यदि तुम सच्चे हो।"},{"a":144,"ar":"وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَـٰذَا ۚ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ","en":"And of the camels, two and of the cattle, two. Say, \"Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Or were you witnesses when Allāh charged you with this? Then who is more unjust than one who invents a lie about Allāh to mislead the people by [something] other than knowledge? Indeed, Allāh does not guide the wrongdoing people.\"","ur":"اور دو (دو) اونٹوں میں سے اور دو (دو) گایوں میں سے (ان کے بارے میں بھی ان سے) پوچھو کہ (خدا نے) دونوں (کے) نروں کو حرام کیا ہے یا دونوں (کی) مادنیوں کو یا جو بچہ مادنیوں کے پیٹ میں لپٹ رہا ہو اس کو بھلا جس وقت خدا نے تم کو اس کا حکم دیا تھا تم اس وقت موجود تھے؟ تو اس شخص سے زیادہ کون ظالم ہے جو خدا پر جھوٹ افتراء کرے تاکہ اِز راہ بے دانشی لوگوں کو گمراہ کرے کچھ شک نہیں کہ خدا ظالم لوگوں کو ہدایت نہیں دیتا","hi":"और ऊँट में से दो तथा गाय में से दो। आप पूछिए कि क्या अल्लाह ने दोनों नर हराम किए हैं अथवा दोनों मादा या उसे जो दोनों मादा के पेट में हो? क्या तुम उस समय उपस्थित थे, जब अल्लाह ने तुम्हें इसका आदेश दिया था? फिर उससे बड़ा अत्याचारी कौन होगा, जो अल्लाह पर झूठ गढ़े ताकि लोगों को बिना किसी ज्ञान के गुमराह करे? निश्चय अल्लाह अत्याचारियों को सत्य का मार्ग नहीं दिखाता।"},{"a":145,"ar":"قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۚ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ","en":"Say, \"I do not find within that which was revealed to me [anything] forbidden to one who would eat it unless it be a dead animal or blood spilled out or the flesh of swine - for indeed, it is impure - or it be [that slaughtered in] disobedience, dedicated to other than Allāh. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], then indeed, your Lord is Forgiving and Merciful.\"","ur":"کہو کہ جو احکام مجھ پر نازل ہوئے ہیں ان میں کوئی چیز جسے کھانے والا کھائے حرام نہیں پاتا بجز اس کے کہ وہ مرا ہوا جانور یا بہتا لہو یا سور کا گوشت کہ یہ سب ناپاک ہیں یا کوئی گناہ کی چیز ہو کہ اس پر خدا کے سوا کسی اور کا نام لیا گیا ہو اور اگر کوئی مجبور ہو جائے لیکن نہ تو نافرمانی کرے اور نہ حد سے باہر نکل جائے تو تمہارا پروردگار بخشنے والا مہربان ہے","hi":"(ऐ नबी!) आप कह दें कि मेरी ओर जो वह़्य (प्रकाशना) की गई है, उसमें मैं किसी खाने वाले पर, कोई चीज़ जो वह खाना चाहे, हराम नहीं पाता, सिवाय इसके कि मुरदार हो या बहता हुआ रक्त हो या सूअर का मांस हो; क्योंकि वह निश्चय ही नापाक है, या अवैध हो, जिसे अल्लाह के सिवा दूसरे के नाम पर ज़बह किया गया हो। परंतु जो विवश हो जाए (तो वह खा सकता है) यदि वह विद्रोही तथा सीमा लाँघने वाला न हो। निःसंदेह आपका पालनहार अति क्षमा करने वाला, अत्यंत दयावान् है।"},{"a":146,"ar":"وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ ۖ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ۚ ذَٰلِكَ جَزَيْنَـٰهُم بِبَغْيِهِمْ ۖ وَإِنَّا لَصَـٰدِقُونَ","en":"And to those who are Jews We prohibited every animal of uncloven hoof; and of the cattle and the sheep We prohibited to them their fat, except what adheres to their backs or the entrails or what is joined with bone. [By] that We repaid them for their transgression. And indeed, We are truthful.","ur":"اور یہودیوں پر ہم نے سب ناخن والے جانور حرام کر دئیے تھے اور گایوں اور بکریوں سے ان کی چربی حرام کر دی تھی سوا اس کے جو ان کی پیٹھ پر لگی ہو یا اوجھڑی میں ہو یا ہڈی میں ملی ہو یہ سزا ہم نے ان کو ان کی شرارت کے سبب دی تھی اور ہم تو سچ کہنے والے ہیں","hi":"तथा हमने यहूदियों पर नाखून वाले जानवर ह़राम कर दियए थे और उनपर गाय एवं बकरी की चर्बियाँ भी हराम कर दी थीं। परंतु जो दोनों की पीठों या आँतों से लगी हों अथवा जो किसी हड्डी से मिली हुई हो (हलाल है)। हमने उन्हें यह बदला उनकी अवज्ञा के कारण दिया था। तथा निश्चय ही हम सच्चे हैं।"},{"a":147,"ar":"فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ","en":"So if they deny you, [O Muḥammad], say, \"Your Lord is the possessor of vast mercy; but His punishment cannot be repelled from the people who are criminals.\"","ur":"اور اگر یوں لوگ تمہاری تکذیب کریں تو کہہ دو تمہارا پروردگار صاحب رحمت وسیع ہے مگر اس کا عذاب گنہ گاروں لوگوں سے نہیں ٹلے گا","hi":"फिर (ऐ नबी!) यदि ये लोग आपको झुठलाएँ, तो कह दें कि तुम्हारा पालनहार व्यापक दया का मालिक है तथा उसकी यातना को अपराधियों से फेरा नहीं जा सकेगा।"},{"a":148,"ar":"سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا ۗ قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ ۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ","en":"Those who associated [others] with Allāh will say, \"If Allāh had willed, we would not have associated [anything] and neither would our fathers, nor would we have prohibited anything.\" Likewise did those before deny until they tasted Our punishment. Say, \"Do you have any knowledge that you can produce for us? You follow not except assumption, and you are not but misjudging.\"","ur":"جو لوگ شرک کرتے ہیں وہ کہیں گے کہ اگر خدا چاہتا تو ہم شرک نہ کرتے اور نہ ہمارے باپ دادا (شرک کرتے) اور نہ ہم کسی چیز کو حرام ٹھہراتے اسی طرح ان لوگوں نے تکذیب کی تھی جو ان سے پہلے تھے یہاں تک کہ ہمارے عذاب کا مزہ چکھ کر رہے کہہ دو کیا تمہارے پاس کوئی سند ہے (اگر ہے) تو اسے ہمارے سامنے نکالو تم محض خیال کے پیچھے چلتے اور اٹکل کی تیر چلاتے ہو","hi":"बहुदेववादी अवश्य कहेंगे कि यदि अल्लाह चाहता, तो हम तथा हमारे पूर्वज (अल्लाह का) साझी न बनाते और न हम किसी चीज़ को हराम ठहराते। ऐसे ही इनसे पहले के लोगों ने भी झुठलाया था, तो उन्हें हमारी यातना का स्वाद चखना पड़ा। (ऐ नबी!) उनसे पूछिए कि क्या तुम्हारे पास (इस विषय में) कोई ज्ञान है, जिसे तुम हमारे समक्ष प्रस्तुत कर सको? तुम तो केवल अनुमान पर चलते हो और केवल अटकल से काम लेते हो।"},{"a":149,"ar":"قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَـٰلِغَةُ ۖ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ","en":"Say, \"With Allāh is the far-reaching [i.e., conclusive] argument. If He had willed, He would have guided you all.\"","ur":"کہہ دو کہ خدا ہی کی حجت غالب ہے اگر وہ چاہتا تو تم سب کو ہدایت دے دیتا","hi":"(ऐ नबी!) आप कह दें कि पूर्ण तर्क तो अल्लाह ही का है। सो यदि वह चाहता, तो तुम सबको सीधे मार्ग पर लगा देता।"},{"a":150,"ar":"قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَـٰذَا ۖ فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ ۚ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ","en":"Say, [O Muḥammad], \"Bring forward your witnesses who will testify that Allāh has prohibited this.\" And if they testify, do not testify with them. And do not follow the desires of those who deny Our verses and those who do not believe in the Hereafter, while they equate [others] with their Lord.","ur":"کہو کہ اپنے گواہوں کو لاؤ جو بتائیں کہ خدا نے یہ چیزیں حرام کی ہیں پھر اگر وہ (آ کر) گواہی دیں تو تم ان کے ساتھ گواہی نہ دینا اور نہ ان لوگوں کی خواہشوں کی پیروی کرنا جو ہماری آیتوں کو جھٹلاتے ہیں اور آخرت پر ایمان نہیں لاتے اور (بتوں کو) اپنے پروردگار کے برابر ٹھہراتے ہیں","hi":"आप कह दें कि अपने गवाहों को लाओ, जो गवाही दें कि इसे अल्लाह ही ने हराम ठहराया है। फिर यदि वे गवाही दें, तो आप उनकी गवाही को न मानें। और उन लोगों की इच्छाओं पर न चलें, जिन्होंने हमारी आयतों को झुठलाया और जो आख़िरत पर विश्वास नहीं रखते तथा दूसरों को अपने पालनहार का समकक्ष ठहराते हैं।"},{"a":151,"ar":"۞ قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَـٰنًا ۖ وَلَا تَقْتُلُوٓا۟ أَوْلَـٰدَكُم مِّنْ إِمْلَـٰقٍ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ","en":"Say, \"Come, I will recite what your Lord has prohibited to you. [He commands] that you not associate anything with Him, and to parents, good treatment, and do not kill your children out of poverty; We will provide for you and them. And do not approach immoralities - what is apparent of them and what is concealed. And do not kill the soul which Allāh has forbidden [to be killed] except by [legal] right. This has He instructed you that you may use reason.\"","ur":"کہہ کہ (لوگو) آؤ میں تمہیں وہ چیزیں پڑھ کر سناؤں جو تمہارے پروردگار نے تم پر حرام کر دی ہیں (ان کی نسبت اس نے اس طرح ارشاد فرمایا ہے) کہ کسی چیز کو خدا کا شریک نہ بنانا اور ماں باپ (سے بدسلوکی نہ کرنا بلکہ) سلوک کرتے رہنا اور ناداری (کے اندیشے) سے اپنی اولاد کو قتل نہ کرنا کیونکہ تم کو اور ان کو ہم ہی رزق دیتے ہیں اور بےحیائی کے کام ظاہر ہوں یا پوشیدہ ان کے پاس نہ پھٹکنا اور کسی جان (والے) کو جس کے قتل کو خدا نے حرام کر دیا ہے قتل نہ کرنا مگر جائز طور پر (یعنی جس کا شریعت حکم دے) ان باتوں کا وہ تمہیں ارشاد فرماتا ہے تاکہ تم سمجھو","hi":"आप उनसे कह दें कि आओ, मैं तुम्हें (आयतें) पढ़कर सुना दूँ कि तुमपर, तुम्हारे पालनहार ने क्या हराम किया है? वह यह है कि किसी चीज़ को अल्लाह का साझी न बनाओ और माता-पिता के साथ उपकार करो तथा निर्धनता के भय से अपनी संतानों की हत्या न करो। हम तुम्हें रोज़ी देते हैं और उन्हें भी देंगे। और निर्लज्जता की बातों के निकट भी न जाओ, खुली हों अथवा छिपी। और किसी प्राणी की हत्य न करो, जिस (की हत्या) को अल्लाह ने हराम ठहराया हो, सिवाय इसके कि उसका कोई उचित कारण हो। ये बातें हैं, जिनकी अल्लाह ने तुम्हें ताकीद की है, ताकि तुम समझो।"},{"a":152,"ar":"وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۖ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ","en":"And do not approach the orphan's property except in a way that is best [i.e., intending improvement] until he reaches maturity. And give full measure and weight in justice. We do not charge any soul except [with that within] its capacity. And when you speak [i.e., testify], be just, even if [it concerns] a near relative. And the covenant of Allāh fulfill. This has He instructed you that you may remember.","ur":"اور یتیم کے مال کے پاس بھی نہ جانا مگر ایسے طریق سے کہ بہت ہی پسندیدہ ہو یہاں تک کہ وہ جوانی کو پہنچ جائے اور ناپ تول انصاف کے ساتھ پوری پوری کیا کرو ہم کسی کو تکلیف نہیں دیتے مگر اس کی طاقت کے مطابق اور جب (کسی کی نسبت) کوئی بات کہو تو انصاف سے کہو گو وہ (تمہارا) رشتہ دار ہی ہو اور خدا کے عہد کو پورا کرو ان باتوں کا خدا تمہیں حکم دیتا ہے تاکہ تم نصحیت کرو","hi":"और अनाथ के धन के पास न जाओ, परंतु ऐसे ढंग से जो उचित हो। यहाँ तक कि वह अपनी युवा अवस्था को पहुँच जाए। तथा नाप-तौल न्याय के साथ पूरा करो। हम किसी प्राणी पर उसकी शक्ति से अधिक बोझ नहीं डालते। और जब बोलो, तो न्याय की बात बोलो, यद्यपि मामला किसी निकटवर्ती का ही क्यों न हो। और अल्लाह का वचन पूरा करो। उसने तुम्हें इन बातों की ताकीद की है, ताकि तुम याद रखो।"},{"a":153,"ar":"وَأَنَّ هَـٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ","en":"And, [moreover], this is My path, which is straight, so follow it; and do not follow [other] ways, for you will be separated from His way. This has He instructed you that you may become righteous.","ur":"اور یہ کہ میرا سیدھا رستہ یہی ہے تو تم اسی پر چلنا اور اور رستوں پر نہ چلنا کہ (ان پر چل کر) خدا کے رستے سے الگ ہو جاؤ گے ان باتوں کا خدا تمہیں حکم دیتا ہے تاکہ تم پرہیزگار بنو","hi":"तथा यह कि यही मेरा सीधा मार्ग है। सो तुम उसी पर चलो। और दूसरी राहों पर न चलो, अन्यथा वे तुम्हें उसकी राह से हटाकर इधर-उधर कर देंगे। यही वह बात है, जिसकी ताकीद उसने तुम्हें की है, ताकि तुम उसके आज्ञाकारी रहो।"},{"a":154,"ar":"ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ","en":"Then We gave Moses the Scripture, making complete [Our favor] upon the one who did good [i.e., Moses] and as a detailed explanation of all things and as guidance and mercy that perhaps in the meeting with their Lord they would believe.","ur":"(ہاں) پھر (سن لو کہ) ہم نے موسیؑ کو کتاب عنایت کی تھی تاکہ ان لوگوں پر جو نیکوکار ہیں نعمت پوری کر دیں اور (اس میں) ہر چیز کا بیان (ہے) اور ہدایت (ہے) اور رحمت ہے تاکہ (ان کی امت کے) لوگ اپنے پروردگار کے رُوبرو حاضر ہونے کا یقین کریں","hi":"फिर हमने मूसा को पुस्तक प्रदान की, उनके अच्छे काम के लिए बदला के रूप में अनुग्रह को पूरा करने के लिए, तथा प्रत्येक वस्तु के विवरण और मार्गदर्शन एवं दया के लिए। ताकि वे अपने पालनहार से मिलने पर मिलने पर ईमान ले आएँ।"},{"a":155,"ar":"وَهَـٰذَا كِتَـٰبٌ أَنزَلْنَـٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ","en":"And this [Qur’ān] is a Book We have revealed [which is] blessed, so follow it and fear Allāh that you may receive mercy.","ur":"اور (اے کفر کرنے والوں) یہ کتاب بھی ہمیں نے اتاری ہے برکت والی تو اس کی پیروی کرو اور (خدا سے) ڈرو تاکہ تم پر مہربانی کی جائے","hi":"तथा यह एक बरकत वाली पुस्तक है, जिसे हमने उतारा है। अतः इसका अनुसरण करो और अल्लाह से डरते रहो, ताकि तुमपर दया की जाए।"},{"a":156,"ar":"أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَـٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَـٰفِلِينَ","en":"[We revealed it] lest you say, \"The Scripture was only sent down to two groups before us, but we were of their study unaware,\"","ur":"(اور اس لیے اتاری ہے) کہ (تم یوں نہ) کہو کہ ہم سے پہلے دو ہی گروہوں پر کتابیں اتری تھیں اور ہم ان کے پڑھنے سے (معذور اور) بےخبر تھے","hi":"ताकि (ऐ अरब वासियो!) तुम यह न कहो कि पुस्तक तो हमसे पहले के दो समुदायों (यहूदी तथा ईसाई) पर उतारी गई थी और निश्चय हम उनके पढ़ने-पढ़ाने से अनजान थे।"},{"a":157,"ar":"أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَـٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ ۚ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ ۚ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَـٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا ۗ سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَـٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ","en":"Or lest you say, \"If only the Scripture had been revealed to us, we would have been better guided than they.\" So there has [now] come to you a clear evidence from your Lord and a guidance and mercy. Then who is more unjust than one who denies the verses of Allāh and turns away from them? We will recompense those who turn away from Our verses with the worst of punishment for their having turned away.","ur":"یا (یہ نہ) کہو کہ اگر ہم پر بھی کتاب نازل ہوتی تو ہم ان لوگوں کی نسبت کہیں سیدھے رستے پر ہوتے سو تمہارے پاس تمہارے پروردگار کی طرف سے دلیل اور ہدایت اور رحمت آ گئی ہے تو اس سے بڑھ کر ظالم کون ہوگا جو خدا کی آیتوں کی تکذیب کرے اور ان سے (لوگوں کو) پھیرے جو لوگ ہماری آیتوں سے پھیرتے ہیں اس پھیرنے کے سبب ہم ان کو برے عذاب کی سزا دیں گے","hi":"या यह न कहो कि यदि हमपर पुस्तक उतारी गई होती, तो हम उनसे भी अधिक सीधी राह पर होते। तो लो, अब तुम्हारे पास तुम्हारे पालनहार की ओर से एक खुला तर्क और मार्गदर्शन एवं दया आ चुकी है। अतः उससे बड़ा अत्यचारी कौन होगा, जो अल्लाह की आयतों को मिथ्या कहे और उनसे कतरा जाए? और जो लोग हमारी आयतों से कतराते हैं, हम उनके कतराने के बदले उन्हें कड़ी यातना देंगे।"},{"a":158,"ar":"هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَـٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَـٰتِ رَبِّكَ ۗ يَوْمَ يَأْتِى بَعْضُ ءَايَـٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَـٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَـٰنِهَا خَيْرًا ۗ قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ","en":"Do they [then] wait for anything except that the angels should come to them or your Lord should come or that there come some of the signs of your Lord? The Day that some of the signs of your Lord will come no soul will benefit from its faith as long as it had not believed before or had earned through its faith some good. Say, \"Wait. Indeed, we [also] are waiting.\"","ur":"یہ اس کے سوا اور کس بات کے منتظر ہیں کہ ان کے پاس فرشتے آئیں یا خود تمہارا پروردگار آئے یا تمہارے پروردگار کی کچھ نشانیاں آئیں (مگر) جس روز تمہارے پروردگار کی کچھ نشانیاں آ جائیں گی تو جو شخص پہلے ایمان نہیں لایا ہوگا اس وقت اسے ایمان لانا کچھ فائدہ نہیں دے گا یا اپنے ایمان (کی حالت) میں نیک عمل نہیں کئے ہوں گے (تو گناہوں سے توبہ کرنا مفید نہ ہوگا اے پیغمبر ان سے) کہہ دو کہ تم بھی انتظار کرو ہم بھی انتظار کرتے ہیں","hi":"क्या वे इसी बात की प्रतीक्षा कर रहे हैं कि उनके पास फ़रिश्ते आ जाएँ, या स्वयं उनका पालनहार आ जाए या आपके पालनहार की कोई निशानी आ जाए? जिस दिन आपके पालनहार की कोई निशानी आ जाएगी, तो किसी प्राणी को उसका ईमान लाभ नहीं देगा, जो पहले ईमान न लाया हो या अपने ईमान की हालत में कोई सत्कर्म न किया हो। आप कह दें कि तुम प्रतीक्षा करो, हम भी प्रतीक्षा कर रहे हैं।"},{"a":159,"ar":"إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ ۚ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ","en":"Indeed, those who have divided their religion and become sects - you, [O Muḥammad], are not [associated] with them in anything. Their affair is only [left] to Allāh; then He will inform them about what they used to do.","ur":"جن لوگوں نے اپنے دین میں (بہت سے) رستے نکالے اور کئی کئی فرقے ہو گئے ان سے تم کو کچھ کام نہیں ان کا کام خدا کے حوالے پھر جو کچھ وہ کرتے رہے ہیں وہ ان کو (سب) بتائے گا","hi":"जिन लोगों ने अपने धर्म के टुकड़े-टुकड़े कर लिए और विभिन्न गिरोहों में बट गए, आपका उनसे कोई संबंध नहीं। उनका मामला अल्लाह के हवाले है। फिर वह उन्हें बता देगा कि वे क्या करते रहे हैं।"},{"a":160,"ar":"مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ","en":"Whoever comes [on the Day of Judgement] with a good deed will have ten times the like thereof [to his credit], and whoever comes with an evil deed will not be recompensed except the like thereof; and they will not be wronged.","ur":"اور جو کوئی (خدا کے حضور) نیکی لے کر آئے گا اس کو ویسی دس نیکیاں ملیں گی اور جو برائی لائے گا اسے سزا ویسے ہی ملے گی اور ان پر ظلم نہیں کیا جائے گا","hi":"जो (क़ियामत के दिन) एक नेकी लेकर आएगा, उसे उसका दस गुना बदला मिलेगा और जो एक बुराई लेकर आएगा, उसे उसका बस उतना ही बदला दिया जाएगा और उनपर कोई अत्याचार नहीं किया जाएगा।"},{"a":161,"ar":"قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۚ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","en":"Say, \"Indeed, my Lord has guided me to a straight path - a correct religion - the way of Abraham, inclining toward truth. And he was not among those who associated others with Allāh.\"","ur":"کہہ دو کہ مجھے میرے پروردگار نے سیدھا رستہ دکھا دیا ہے (یعنی دین صحیح) مذہب ابراہیم کا جو ایک (خدا) ہی کی طرف کے تھے اور مشرکوں میں سے نہ تھے","hi":"(ऐ नबी!) आप कह दें कि यकीनन मेरे पालनहार ने मुझे सीधी राह दिखा दी है। वही सीधा धर्म, जो एकेश्वरवादी इबराहीम का धर्म था। और वह बहुदेववादियों में से न था।"},{"a":162,"ar":"قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ","en":"Say, \"Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allāh, Lord of the worlds.","ur":"(یہ بھی) کہہ دو کہ میری نماز اور میری عبادت اور میرا جینا اور میرا مرنا سب خدائے رب العالمین ہی کے لیے ہے","hi":"आप कह दें कि निश्चय मेरी नमाज़, मेरी क़ुरबानी तथा मेरा जीवन-मरण सारे संसारों के पालनहार अल्लाह के लिए हैl"},{"a":163,"ar":"لَا شَرِيكَ لَهُۥ ۖ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ","en":"No partner has He. And this I have been commanded, and I am the first [among you] of the Muslims.\"","ur":"جس کا کوئی شریک نہیں اور مجھ کو اسی بات کا حکم ملا ہے اور میں سب سے اول فرمانبردار ہوں","hi":"उसका कोई साझी नहीं। मुझे इसी का आदेश दिया गया है। और मैं सबसे पहला मुसलमान हूँ।"},{"a":164,"ar":"قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ ۚ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ","en":"Say, \"Is it other than Allāh I should desire as a lord while He is the Lord of all things? And every soul earns not [blame] except against itself, and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you concerning that over which you used to differ.\"","ur":"کہو کیا میں خدا کے سوا اور پروردگار تلاش کروں اور وہی تو ہر چیز کا مالک ہے اور جو کوئی (برا) کام کرتا ہے تو اس کا ضرر اسی کو ہوتا ہے اور کوئی شخص کسی (کے گناہ) کا بوجھ نہیں اٹھائے گا پھر تم سب کو اپنے پروردگار کی طرف لوٹ کا جانا ہے تو جن جن باتوں میں تم اختلاف کیا کرتے تھے وہ تم کو بتائے گا","hi":"आप (उनसे) कह दें कि क्या मैं अल्लाह के सिवा किसी और पालनहार की खोज करूँ? जबकि वह प्रत्येक वस्तु का पालनहार है। तथा जो भी प्राणी कोई कार्य करेगा, उसका फल वही भोगेगा। और कोई किसी दूसरे का बोझ नहीं उठाएगा। फिर (अंततः) तुम्हें अपने पालनहार के पास ही जाना है। उस समय वह तुम्हें बता देगा, जिसमें तुम मतभेद किया करते थे।"},{"a":165,"ar":"وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَـٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَـٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۗ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ","en":"And it is He who has made you successors upon the earth and has raised some of you above others in degrees [of rank] that He may try you through what He has given you. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.","ur":"اور وہی تو ہے جس نے زمین میں تم کو اپنا نائب بنایا اور ایک کے دوسرے پر درجے بلند کئے تاکہ جو کچھ اس نے تمہیں بخشا ہے اس میں تمہاری آزمائش ہے بےشک تمہارا پروردگار جلد عذاب دینے والا ہے اور بےشک وہ بخشنے والا مہربان بھی ہے","hi":"और वही है, जिसने तुम्हें धरती में उत्तराधिकारी बनाया और तुममें से कुछ लोगों के दरजे दूसरे लोगों की अपेक्षा ऊँचे रखे। ताकि उसने तुम्हें जो कुछ दिया है, उसमें तुम्हारी परीक्षा ले। निश्चय आपका पालनहार शीघ्र ही दंड देने वाला है। और निश्चय वह बहुत क्षमा करने वाला, अत्यंत दयावान् है।"}],"tlx":{"hi":"अल-अनआम","ur":"الأنعام"}};
